window.__LEX={"G400":"<h1>anaphoneo</h1>\n<p>Strong n° 400 <i>Prononciation [an-af-o-neh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>crier d'une forte voix, s'écrier, s'exclamer</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀναφωνέω</b> <b>ἀνα·φωνέω-ῶ :<br> 1</b> pousser de grands cris, POL. <i>3, 33, 4 ;</i><br><b> 2</b> proclamer : τινα βασιλέα, PLUT. <i>Demetr. 18,</i> qqn roi ;<br><b> 3</b> dire avec emphase <i>ou</i> par exagération poétique, ARSTT. <i>Mund. 6 ;</i> PLUT. <i>Cor. 32 ;</i><br><b> 4</b> déclamer : τὰ ἀναπεφωνημένα, PLUT. <i>M. 30</i> e, déclamations ; <i>particul</i>. exercer sa voix en déclamant, PLUT. <i>M. 130</i> c.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ανα-φωνεω - ἀναφωνέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G401":"<h1>anachusis</h1>\n<p>Strong n° 401 <i>Prononciation [an-akh'-oo-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un débordement, un liquide qui se renverse</li>\n<li>métaph. l'excès (inondation) auquel amène une vie dissolue</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀνάχυσις, εως (ἡ)</b> <span>[ῠ]</span><br><b>      1</b> épanchement (de bile) ARÉT. <i>Caus. m. diut. 1, 15 ; fig</i>. épanchement (de l’âme) PHIL. <i>2, 187 ; en mauv. part,</i> désordre des mœurs, NT. <i>1Petr. 4, 4 ;</i><br><b>      2</b> estuaire, STR. <i>140</i>.<br><span><b>Étym</b>. ἀναχέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ανα-χυσις - ἀνάχυσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G402":"<h1>anachoreo</h1>\n<p>Strong n° 402 <i>Prononciation [an-akh-o-reh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>repartir, retourner, s'éloigner</li>\n<li>se retirer\n<ol type=\"a\">\n<li>comme en quittant une pièce</li>\n<li>celui qui par crainte cherche un autre lieu</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀνα·χωρέω-ῶ</b>, aller en arrière, <i>d’où :</i><br><b>      1</b> retourner sur ses pas : πόλινδε ἂψ ἀν. IL. <i>10, 210,</i> retourner à la ville ; ἀν. ἐπ' οἴκου, THC. <i>1, 30,</i> revenir chez soi ;<br><b>      2</b> reculer (devant l’ennemi) IL. <i>4, 305, etc. ;</i> THC. <i>8, 15 ;</i> φυγῇ ἀν. PLAT. <i>Conv. 221</i> a, battre en retraite ;<br><b>      3</b> se retirer, s’éloigner : ὀπίσω, HDT. <i>4, 183, etc. ;</i> εἰς τοὐπίσω, PLAT. <i>Menex. 246</i> b ; LYS. <i>140, 6 ;</i> ἐς τοὔπισθεν, AR. <i>Pl. 1208,</i> se retirer en arrière, s’éloigner : <i>avec un gén. :</i> ἀν. μεγάροιο, OD. <i>22, 270,</i> se retirer du palais ; τῆς τῶν πολλῶν ὄψεως, EL. <i>N.A. 3, 30,</i> de la vue de la foule ; ἐς τὴν ἀκρόπολιν, HDT. <i>3, 143,</i> dans l’acropole ; ὑπό τινος, HDT. <i>5, 61,</i> être forcé par qqn de se retirer : <i>fig</i>. ἐκ τῶν πραγμάτων, POL. <i>29, 10, 5,</i> se retirer des affaires publiques, <i>d’où</i> se retirer, s’abstenir : ἔκ τινος, PLAT. <i>Phæd. 23</i> a, s’abstenir de qqe ch. ; <i>abs</i>. THC. <i>4, 28 ;</i> POL. <i>26, 1, 5 ;</i><br><b>      4</b> <i>intr. au pf</i>. ἀνακεχώρηκα : χώρα ἀνακεχωρηκυῖα, TH. <i>H.P. 9, 7, 4,</i> pays écarté ; πολισμάτιον ἀνακεχωρηκὸς ἀπὸ τῆς θαλάσσης, POL. <i>2, 11, 16,</i> petite ville éloignée de la mer ; <i>fig</i>. ῥῆμα ἀνακεχωρηκός, DH. <i>Rhet. 7,</i> expression tombée en désuétude ;<br><b>      5</b> passer par succession à, revenir à : ἡ βασιληΐη ἀνεχώρεε ἐς τὸν παῖδα, HDT. <i>7, 4,</i> la royauté revenait à son fils ; ἡ ποινὴ εἰς ἡμᾶς ἀναχωρεῖ, ANT. <i>115, 13,</i> la peine retombe sur nous.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ανα-χωρεω - ἀναχωρέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n14 fois dans 14 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (10)</li>\n<li>Marc (1)</li>\n<li>Jean (1)</li>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G403":"<h1>anapsuxis</h1>\n<p>Strong n° 403 <i>Prononciation [an-aps'-ook-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>fraîchement, fraîchissant, rafraîchissement</li>\n<li>rafraîchissement (terme médical appliqué au temps messianique)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀνάψυξις, εως (ἡ)</b> :<br>      1</b> action de rafraîchir, rafraîchissement, HPC. <i>Fract. 767 ;</i><br><b>      2</b> <i>fig</i>. soulagement, allègement, STR. <i>459</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ανα-ψυχξις - ἀνάψυξις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G404":"<h1>anapsucho</h1>\n<p>Strong n° 404 <i>Prononciation [an-aps-oo'-kho]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>rafraîchir, réparer les effets de la chaleur\n<ol type=\"a\">\n<li>se rafraîchir l'esprit</li>\n</ol>\n</li>\n<li>retrouver la respiration, prendre l'air, revivre, se rafraîchir, être consolé, réconforté</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀνα·ψύχω</b> <span>[ῡ]</span> <span>(<i>f</i>. ύξω, <i>ao</i>. ἀνέψυξα, <i>pf. inus. ; pass. ao</i>. ἀνεψύχθην ; <i>ao.2</i> ἀνεψύγην)</span><br><b>   I <i>tr</i>.<br>      1</b> ranimer par un air frais, rafraîchir : ἀνθρώπους, OD. <i>4, 568,</i> les hommes, <i>en parl. de la brise de mer ; p. anal</i>. ἀν. θηλύπουν βάσιν, EUR. <i>I.A. 421</i> reposer (<i>litt</i>. rafraîchir) ses jambes de femme (après avoir longtemps voyagé en voiture) ; <i>fig</i>. rafraîchir, soulager : ἦτορ, IL. <i>13, 84,</i> le cœur ; ἕλκος, IL. <i>5, 795,</i> une blessure ; πόνων τινά, EUR. <i>Hel. 1094,</i> délivrer qqn de ses maux ;<br><b>      2</b> <i>p. suite,</i> faire sécher : ναῦς, XÉN. <i>Hell. 1, 5, 10,</i> des navires ; ἱδρῶτα, PLUT. <i>Syll. 29,</i> la sueur ;<br><b>   II <i>intr.</i></b> reprendre haleine, respirer : πόνοιο, OPP. <i>H. 5, 623,</i> se reposer d’une fatigue ; <i>abs</i>. DIPH. (<i>Bkk. 80, 29</i>) ; DH. <i>9, 12 ;</i> ATH. <i>503</i> c ; NIC. <i>Th. 312 ;</i> ANTH. <i>12, 132 ;</i><br><b><i>Moy.</i></b> se reposer, se remettre, PLAT. <i>Tim. 78</i> e.<br><span><b><span class=\"arrow\"></span></b> <i>Impf. itér. 3 sg</i>. ἀναψύχεσκε, ORPH. <i>Lith. 556. Ao. pass. 3 pl. épq</i>. ἀνέψυχθεν, IL. <i>10, 575</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ανα-ψυχω - ἀναψύχω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G405":"<h1>andrapodistes</h1>\n<p>Strong n° 405 <i>Prononciation [an-drap-od-is-tace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un marchand d'esclaves, kidnappeur\n<ol type=\"a\">\n<li>celui qui réduit injustement l'homme libre à l'esclavage</li>\n<li>celui qui vole les esclaves des autres pour les vendre</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀνδραποδιστής, </b><b>οῦ (ὁ)</b> <span>[ᾰπ]</span> qui réduit en servitude des hommes libres, LYS. <i>117, 8 ;</i> AR. <i>Pl. 522, etc. ; joint à</i> βωμολόχους, AR. <i>Th. 818 ; à</i> ἱερόσυλοι <i>et à</i> τοιχωρύχοι, PLAT. <i>Rsp. 344</i> b, <i>etc. ;</i> ἀ. ἑαυτοῦ, XÉN. <i>Mem. 1, 2, 6,</i> qui aliène sa liberté.<br><span><b>Étym</b>. ἀνδραποδίζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ανδραποδιστης - ἀνδραποδιστής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G406":"<h1>Andreas</h1>\n<p>Strong n° 406 <i>Prononciation [an-dreh'-as]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>André (Angl. Andrew) = « virilité »\n<ol><li>natif de Bethsaïda en Galilée, frère de Simon Pierre, un disciple de Jean-Baptiste, et ensuite un apôtre de Christ. Il est dit qu'il fut crucifié en Achaïe.</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ἀνδρέας, </b><b>-α, -ᾳ, -αν (ὁ)</b> Andréas (Andrée) <i>h</i>. HDT. <i>6, 126, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Voc</i>. -έα, ANTH. <i>7, 673. Gén. ion. et épq</i>. -εω, HDT. <i>l. c. ;</i> ANTH. <i>7, 672</i>.<br><span><b>Étym</b>. ἀνήρ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ανδρεας - Ἀνδρέας</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n13 fois dans 12 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (4)</li>\n<li>Luc (1)</li>\n<li>Jean (5)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G407":"<h1>andrizomai</h1>\n<p>Strong n° 407 <i>Prononciation [an-drid'-zom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être un homme, être brave</li>\n<li>se montrer un homme, être courageux</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<u>Mot apparenté</u> : <b>ἀνδρίζω</b> (<i>seul. prés</i>.) rendre fort comme un homme, fortifier, XÉN. <i>Œc. 5, 4 ;</i><br><b><i>Moy.</i></b> (<i>seul. prés. et impf</i>. ἠνδριζόμην) :<br><b>      1</b> être parvenu à l’âge d’homme, AR. <i>fr. 653 ;</i><br><b>      2</b> agir en homme, <i>càd</i>. virilement, XÉN. <i>An. 4, 3, 34, etc. ;</i> PLAT. <i>Theæt. 151</i> d ; ARSTT. <i>Nic. 3, 6, 12 ;</i> PLUT. <i>M. 1046</i> f, <i>1047</i> a ;<br><b>      3</b> porter des vêtements d’homme, PHILSTR. <i>766 ;</i><br><b>      4</b> <i>en mauv. part,</i> être un débauché contre nature, DC. <i>79, 5</i>.<br><span><b>Étym</b>. ἀνήρ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ανδριζομαι - ἀνδρίζομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G408":"<h1>Andronikos</h1>\n<p>Strong n° 408 <i>Prononciation [an-dron'-ee-kos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Andronicus = « homme de la victoire »\n<ol><li>un Juif chrétien, et un parent de Paul</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ἀνδρό·νικος, ου (ὁ)</b> <span>[ῑ]</span> Andronikos, <i>h</i>. PLUT. <i>Syll. 26, etc</i>.<br><span><b><span class=\"arrow\"></span></b> Ἀνδρώνικος, ANTH. <i>App. 339</i>.<br><span><b>Étym</b>. ἀ. νίκη.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ανδροκινος - Ἀνδρόνικος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G409":"<h1>androphonos</h1>\n<p>Strong n° 409 <i>Prononciation [an-drof-on'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>meurtrier, assassin</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀνδρο·φόνος, ος, ον</b> :<br>      1</b> qui tue un homme <i>ou</i> des hommes, homicide, meurtrier, <i>en parl. de pers. et de choses,</i> IL. <i>18, 317, etc. ;</i> OD. <i>1, 261 ; subst</i>. un meurtrier, LYS. <i>116, 38 ;</i> PLAT. <i>Phæd. 114</i> a, <i>Leg. 916</i> c ; DÉM. <i>629 fin ;</i><br><b>      2</b> qui tue son époux, PD. <i>P. 4, 252</i>.<br><span><b>Étym</b>. ἀνήρ, πεφνεῖν.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ανδρο-φονος - ἀνδροφόνος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G410":"<h1>anegkletos</h1>\n<p>Strong n° 410 <i>Prononciation [an-eng'-klay-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>innocent, sans tache, sans reproche, irréprochable, qui ne peut être cité en justice</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀν·έγκλητος, ος, ον</b> :<br>      1</b> sans reproche, irréprochable, XÉN. <i>Mem. 6, 1, 13, etc. ;</i> PLAT. <i>Ep. 329</i> b ; DÉM. <i>1470, 22, etc. ;</i><br><b>      2</b> de façon à ne donner aucun sujet de plainte, PLAT. <i>Leg. 737</i> a.<br><span><b>Étym</b>. ἀν-, ἐγκαλέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αν-εγκλητος - ἀνέγκλητος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 4 livres bibliques (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n<li>Colossiens (1)</li>\n<li>1 Timothée (1)</li>\n<li>Tite (2)</li>\n</ul>\n</td></tr>\n</table>","G411":"<h1>anekdiegetos</h1>\n<p>Strong n° 411 <i>Prononciation [an-ek-dee-ay'-gay-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>ineffable, indescriptible, qu'on ne peut exprimer, inexplicable, indescriptible, qui dépasse le langage</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀν·εκδιήγητος, ος, ον</b>, qu’on ne peut expliquer <i>ou</i> raconter, NT. <i>2Cor. 9, 15</i>.<br><span><b>Étym</b>. ἀν-, ἐκδιηγέομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αν-εκδιηγητος - ἀνεκδιήγητος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G412":"<h1>aneklaletos</h1>\n<p>Strong n° 412 <i>Prononciation [an-ek-lal'-ay-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>inexprimable, indescriptible</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀν·εκλάλητος, ος, ον</b> <span>[λᾰ]</span> inexprimable, NT. <i>1Petr. 1, 8, etc</i>.<br><span><b>Étym</b>. ἀν-, ἐκλαλέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αν-εκλαλητος - ἀνεκλάλητος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G413":"<h1>anekleiptos</h1>\n<p>Strong n° 413 <i>Prononciation [an-ek'-lipe-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sans fin, qui ne viendra pas à manquer</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀν·έκλειπτος, ος, ον</b>, qui ne fait jamais défaut, incessant, perpétuel, DS. <i>4, 84 ;</i> PLUT. <i>M. 438</i> d, <i>etc</i>.<br><span><b>Étym</b>. ἀν-, ἐκλείπω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αν-εκλειπτος - ἀνέκλειπτος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G414":"<h1>anektoteros</h1>\n<p>Strong n° 414 <i>Prononciation [an-ek-tot'-er-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>supportable, tolérable</li>\n<li>avec moins de rigueur</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<u>Mot apparenté</u> : <b>ἀνεκτότης, </b><b>ητος (ἡ)</b> qualité de ce qui est supportable, BAS.<br><span><b>Étym</b>. ἀνεκτός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αν-εκτοτερος - ἀνεκτοτερός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G415":"<h1>aneleemon</h1>\n<p>Strong n° 415 <i>Prononciation [an-eleh-ay'-mone]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sans miséricorde, impitoyable, sans pitié, cruel</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀν·ελεήμων, ων, ον</b>, <i>gén</i>. ονος, sans pitié, cruel, ARSTT. <i>Rhet. Al. 37, 3 ;</i> NT. <i>Rom. 1, 31</i>.<br><span><b>Étym</b>. ἀν-, ἐλ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αν-ελεημων - ἀνελεήμων</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G416":"<h1>anemizo</h1>\n<p>Strong n° 416 <i>Prononciation [an-em-id'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>agité ou poussé par le vent</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀνεμίζω</b> <span>[ᾰ]</span> pousser à l’aide du vent, <i>d’où au pass</i>. être poussé <i>ou</i> agité par le vent, NT. <i>Jac. 1, 6</i>.<br><span><b>Étym</b>. ἄνεμος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ανεμιζω - ἀνεμίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G417":"<h1>anemos</h1>\n<p>Strong n° 417 <i>Prononciation [an'-em-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>vent, violente agitation et courant d'air</li>\n<li>très grosse tempête de vent</li>\n<li>les quatre vents cardinaux, les vents des quatre coins de la terre</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄνεμος, ου (ὁ)</b> <span>[ᾰ]</span> vent :<br><b>A</b> courant de vent :<br><b>   I</b> <i>au propre,</i> IL. <i>12, 207, etc. ;</i> OD. <i>11, 407, etc</i>. : πνοιαὶ ἀνέμοιο, OD. <i>2, 148 ;</i> πνοιαὶ ἀνέμων, OD. <i>4, 839 ;</i> πνοαὶ ἀνέμων, PD. <i>P. 3, 105 ;</i> ἀνέμων ἀήματα, ESCHL. <i>Eum. 905 ;</i> ἀνέμων πνεύματα, ESCHL. <i>Pr. 1087 ;</i> ἀνέμων αὖραι, EUR. <i>Med. 838,</i> les souffles du vent, des vents ; ἀνέμοιο θυέλλη, HÉS. <i>O. 459, etc. ;</i> ἀνέμων ἄελλαι, IL. <i>13, 334, ou</i> ἀέλλη, IL. <i>13, 795,</i> tempête de vent ; ἲς ἀνέμοιο, IL. <i>15, 383 ;</i> βία ἀνέμων, IL. <i>16, 213,</i> la force du vent, des vents ; κατὰ ἄνεμον καὶ ῥοῦν, PLUT. <i>M. 979</i> c, selon le vent et le courant ;<br><b>   II</b> <i>fig. :</i><br><b>      1</b> agitation de l’âme, passion tumultueuse, SOPH. <i>Ant. 929 ;</i><br><b>      2</b> mobilité, inconstance, NT. ;<br><b>B</b> vent dans le corps, flatuosité, HPC. <i>665, 24</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *h₂enh₁-mo-, vent ; <i>cf. lat</i>. animus, <i>sscr</i>. ánila-, <i>rac. sscr</i>. ániti, respirer.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ανεμος - ἄνεμος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n31 fois dans 29 versets de 9 livres bibliques (NT)\n<ul>\n<li>Matthieu (9)</li>\n<li>Marc (7)</li>\n<li>Luc (4)</li>\n<li>Jean (1)</li>\n<li>Actes (4)</li>\n<li>Ephésiens (1)</li>\n<li>Jacques (1)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G418":"<h1>anendektos</h1>\n<p>Strong n° 418 <i>Prononciation [an-en'-dek-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>ce qui ne peut être admis, inadmissible, incroyable, malséant, inacceptable, impossible</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀν·ένδεκτος, ος, ον</b>, inadmissible, impossible, NT. <i>Luc. 17, 1 ;</i> ARTÉM. <i>2, 70</i>.<br><span><b>Étym</b>. ἀν-, ἐνδέχομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ανενδεκτος - ἀνένδεκτος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G419":"<h1>anexereunetos</h1>\n<p>Strong n° 419 <i>Prononciation [an-ex-er-yoo'-nay-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>ce qui ne peut être recherché, trop profond, insondable, impénétrable</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀν·εξεραύνητος, ος, ον</b>, <i>c</i>. ἀνεξερεύνητος, NT. <i>Rom. 11, 33</i>.<br><span><b>Étym</b>. ἀν-, *ἐξεραυνάω ; <i>v</i>. ἐραυνάω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ανεξεραυνητος - ἀνεξεραύνητος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G420":"<h1>anexikakos</h1>\n<p>Strong n° 420 <i>Prononciation [an-ex-ik'-ak-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>patient aux maux, aux fautes, qui supporte la méchanceté</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀνεξί·κακος, ος, ον</b> <span>[ῐᾰ]</span> résigné, LUC. <i>J. voc. 9</i>.<br><span>•<i> Cp</i>. -ώτερος, ARÉT. <i>19, 23 ;</i> <i>• Sup</i>. -ώτατος, THÉM. <i>271</i> b.<br><span><b>Étym</b>. ἀνέχω, κακόν.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αν-εξικακος - ἀνεξίκακος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G421":"<h1>anexichniastos</h1>\n<p>Strong n° 421 <i>Prononciation [an-ex-ikh-nee'-as-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>ce qui ne peut être recherché, ce qui ne peut être compris, dont on ne peut découvrir la trace, impénétrable</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀν·εξιχνίαστος, ος, ον</b>, dont on ne peut saisir la trace, qu’on ne peut découvrir, SPT. <i>Job 5, 9 ; 9, 10 ;</i> NT. <i>Rom. 11, 33 ; Eph. 3, 8</i>.<br><span><b>Étym</b>. ἀν-, ἐξιχνιάζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αν-εξιχνιαστος - ἀνεξιχνίαστος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>Ephésiens (1)</li>\n</ul>\n</td></tr>\n</table>","G422":"<h1>anepaischuntos</h1>\n<p>Strong n° 422 <i>Prononciation [an-ep-ah'-ee-skhoon-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>n'avoir aucune raison d'avoir honte, qui n'a pas à rougir</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀν·επαίσχυντος, ος, ον</b>, irrépréhensible, qui n’a pas à rougir, NT. <i>2Tim. 2, 15</i>.<br><span><b>Étym</b>. ἀν-, ἐπαισχύνομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αν-επαισχυντος - ἀνεπαίσχυντος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G423":"<h1>anepileptos</h1>\n<p>Strong n° 423 <i>Prononciation [an-ep-eel'-ape-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>non répréhensible, qui ne peut entraver</li>\n<li>ce qui ne peut être reproché, non soumis à la censure, sans défaut, irréprochable</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀν·επίλημπτος, ος, ον</b>, <i>c</i>. ἀνεπίληπτος NT. <i>1Tim. 3, 2 ; 5, 7 ; 6, 14</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αν-επιληπτος - ἀνεπίλημπτος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (3)</li>\n</ul>\n</td></tr>\n</table>","G424":"<h1>anerchomai</h1>\n<p>Strong n° 424 <i>Prononciation [an-erkh'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>monter</li>\n<li>aller vers un haut lieu : à Jérusalem</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀν·έρχομαι</b> <span>(<i>f</i>. ἀνελεύσομαι, <i>ao.2</i> ἀνῆλθον, <i>etc</i>.)</span><br><b>   I</b> (ἀνά, en haut) :<br><b>      1</b> monter : ἐς σκοπιήν, OD. <i>10, 97,</i> monter sur un lieu d’observation ; εἰς τὴν ἀκρόπολιν, XÉN. <i>Hell. 2, 4, 39,</i> dans l’acropole ; ἐπὶ τὴν σκηνήν, ARR. <i>Epict. 3, 22, 26,</i> sur la scène ; ἀν. ἐπὶ τὸ βῆμα, HDN <i>1, 5, 4, d’où abs</i>. ἀν. PLUT. <i>Æmil. 31,</i> monter à la tribune ; ἐξ Ἅιδου εἰς θεούς, PLAT. <i>Rsp. 521</i> c, monter des enfers parmi les dieux ; <i>p. anal</i>. se lever, <i>en parl. du soleil,</i> ESCHL. <i>Ag. 658 ;</i> A. RH. <i>3, 1230 ;</i><br><b>      2</b> pousser, croître, <i>en parl. de plantes,</i> OD. <i>6, 163 ;</i><br><b>      3</b> sourdre, jaillir, <i>en parl. d’eau,</i> ARSTT. <i>Meteor. 2, 3, 32, etc. ;</i><br><b>      4</b> <i>en parl. de voyages,</i> aller de la côte dans l’intérieur, OD. <i>19, 190 ;</i><br><b>   II</b> (ἀνά, en arrière) :<br><b>      1</b> revenir sur ses pas, revenir, retourner : ἂψ ἀν. IL. <i>4, 392, ou</i> αὖθις ἀν. OD. <i>1, 317, m. sign. ; fig. en parl. d’un discours, d’un entretien :</i> πάλιν ἐπ' ἀρχὴν ἀν. PLAT. <i>Tim. 69</i> a, revenir au commencement ; ἄνελθέ μοι πάλιν, EUR. <i>Ph. 1207,</i> redis-moi (<i>litt</i>. reviens là-dessus pour me dire) ;<br><b>      2</b> <i>fig</i>. revenir à, passer aux mains de : εἴς τινα, EUR. <i>Hec. 802,</i> être remis entre les mains de qqn.<br><span><b><span class=\"arrow\"></span></b> <span>[ᾱ]</span> IL. <i>4, 392 (var</i>. ἀναέρχ.) ; A. RH. <i>1, 821</i>.<br><span><b>Étym</b>. ἀνά, ἔ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αν-ερχομαι - ἀνέρχομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Jean (1)</li>\n<li>Galates (2)</li>\n</ul>\n</td></tr>\n</table>","G425":"<h1>anesis</h1>\n<p>Strong n° 425 <i>Prononciation [an'-es-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>relâchement, relâche\n<ol type=\"a\">\n<li>se dit d'une meilleure condition de captivité, être tenu dans un confinement moins rigoureux</li>\n<li>soulagement, repos, (par rapport à des persécutions), adoucissement</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄνεσις, εως (ἡ) :<br>   I</b> action de laisser aller, <i>d’où :</i><br><b>      1</b> distension, relâchement (d’une corde, <i>p. opp. à</i> ἐπίτασις, PLAT. <i>Rsp. 349</i> e, <i>etc. ;</i> d’un liquide durci, de glaçons, PLUT. <i>Sert. 17</i>) ;<br><b>      2</b> détente (d’un mal, d’un chagrin, <i>etc</i>.) HDT. <i>5, 28 ;</i> PLUT. <i>M. 102</i> b ;<br><b>      3</b> repos (après un effort) PLAT. <i>Leg. 724</i> a ; <i>joint à</i> σχολή, POL. <i>1, 66, 10 ;</i><br><b>      4</b> relâchement des mœurs, licence, PLAT. <i>Rsp. 561</i> a, <i>etc. ;</i> ARSTT. <i>Pol. 2, 9, 5, etc. ;</i><br><b>   II</b> <i>au sens trans</i>. remise (de dettes, PLUT. <i>Popl. c. Sol. 3 ;</i> d’impôts, PLUT. <i>Sert. 6 ;</i> d’une peine, PLOT. <i>390</i> a).<br><span><b>Étym</b>. ἀνίημι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ανεσις - ἄνεσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td>Les deux mots dénotent un repos temporaire, un répit, par exemple pour des soldats.</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>2 Corinthiens (3)</li>\n<li>2 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G426":"<h1>anetazo</h1>\n<p>Strong n° 426 <i>Prononciation [an-et-ad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>investigation, examen</li>\n<li>examiner d'une manière judiciaire</li>\n<li>interroger sous la torture, mettre à la question</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀν·ετάζω</b> (<i>seul. prés</i>.) :<br><b>      1</b> chercher à savoir : ἀν. τινά τι, SPT. <i>Dan. 14,</i> demander qqe ch. à qqn ;<br><b>      2</b> <i>abs</i>. questionner : τινά, NT. <i>Ap. 22, 29,</i> qqn ; <i>d’où</i> mettre à la question, NT. <i>Ap. 22, 24</i>.<br><span><b>Étym</b>. ἀνά, ἐ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αν-εταζω - ἀνετάζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G427":"<h1>aneu</h1>\n<p>Strong n° 427 <i>Prononciation [an'-yoo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sans sa propre volonté ou intervention</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄνευ</b> <span>[ᾰ]</span> <i>prép</i>. séparément de, <i>avec le gén., d’où :</i><br><b>   I</b> loin de : ἀ. δηΐων, IL. <i>13, 556,</i> hors de l’atteinte de l’ennemi ;<br><b>   II</b> <i>p. suite,</i> hors de, hormis, excepté : πάντα ἄ. χρυσοῦ, PLAT. <i>Criti. 112</i> c, tout excepté de l’or ; ἄνευ τοῦ <i>avec l’inf</i>. DÉM. <i>255, 10,</i> outre que, sans compter que ;<br><b>   III</b> <i>p. suite et d’ord. :</i><br><b>      1</b> sans, <i>dev. un n. de pers. ou de chose, p. opp. à</i> σύν : ἄνευ ἕθεν οὐδὲ σὺν αὐτῷ, IL. <i>17, 407,</i> sans lui ni même avec lui ; ἄνευ κέντροιο, IL. <i>23, 387,</i> sans (avoir besoin de l’) aiguillon ; ἄνευ δεσμοῖο, OD. <i>13, 100,</i> sans lien ; μόνος ἄνευ τινός, AR. <i>Lys. 143 ;</i> PLAT. <i>Conv. 217</i> a, seul sans (un autre) ; ἄνευ φθόνου, SOPH. <i>El. 1466,</i> sans exciter la jalousie des dieux ;<br><b>      2</b> <i>particul</i>. sans la volonté de, malgré : ἄνευ ἐμέθεν, IL. <i>15, 213, ou</i> ἄνευ ἐμοῦ, PLAT. <i>Theag. 122</i> a, sans mon assentiment, malgré moi ; ἄνευ τοῦ κραίνοντος, SOPH. <i>O.C. 926,</i> sans l’aveu du roi ; <i>en ce sens souv. avec une nég. :</i> οὔτι ἄ. θεοῦ, OD. <i>2, 372 ; 15, 530, etc</i>. non malgré une divinité, à l’instigation d’une divinité (<i>cf. lat</i>. non sine diis).<br><span><b><span class=\"arrow\"></span></b> <i>Qqf. après le rég</i>. SOPH. <i>O.C. 502 ;</i> XÉN. <i>Cyr. 6, 1, 14 ; Hell. 7, 1, 3 ;</i> LUC. <i>D. deor. 22, 3, etc</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *sn(H)-, sans, <i>avec psilose ; cf. sscr</i>. sanutár, <i>lat</i>. sine.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ανευ - ἄνευ</font>\n<br><br>particule primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Préposition</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>1 Pierre (2)</li>\n</ul>\n</td></tr>\n</table>","G428":"<h1>aneuthetos</h1>\n<p>Strong n° 428 <i>Prononciation [an-yoo'-the-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>pas commode, non convenable, inadapté</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀν·εύθετος, ος, ον</b>, mal situé, peu convenable, NT. <i>Ap. 27, 12</i>.<br><span><b>Étym</b>. ἀν-, εὔθ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αν-ευθετος - ἀνεύθετος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G429":"<h1>aneurisko</h1>\n<p>Strong n° 429 <i>Prononciation [an-yoo-ris'-ko]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>trouver suite à des recherches, découvrir</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀν·ευρίσκω</b> <span>(<i>f</i>. ἀνευρήσω, <i>ao.2</i> ἀνεῦρον, <i>etc</i>.)</span><br><b>      1</b> découvrir, mettre au jour (une chose cachée) <i>acc</i>. HDT. <i>1, 67, etc. ;</i> XÉN. <i>An. 7, 4, 14 ;</i> PLAT. <i>Tim. 24</i> a, <i>etc. ; au pass</i>. THC. <i>1, 128, etc. ; avec un part</i>. τὰ ἄλλα ἀνεύρηται ὁμοῖα παρεχομένη τῇ Λιϐύῃ, HDT. <i>4, 44,</i> on découvrit que les autres régions (de l’Asie) présentaient les mêmes apparences que la Libye ;<br><b>      2</b> découvrir, inventer, ANTIPH. (<i>Com. fr. 3, 59</i>) ; TIMOCL. (<i>Com. fr. 3, 613), etc. ;</i> PLAT. <i>Phædr. 273</i> c.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. moy. au sens act. 3 sg</i>. ἀνεύρατο (<i>dout., var</i>. ἀνεύρετο) A. RH. <i>4, 1133 ;</i> TIMOCL. (<i>Com. fr. 3, 593</i>).<br><span><b>Étym</b>. ἀνά, εὑρ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αν-ευρισκω - ἀνευρίσκω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G430":"<h1>anechomai</h1>\n<p>Strong n° 430 <i>Prononciation [an-ekh'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>tenir droit, tenir ferme, d'où soutenir, supporter avec constance, tenir</li>\n<li>tenir fermement quelqu'un</li>\n<li>soutenir, porter, endurer, supporter avec courage, supporter courageusement</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀν·έχω</b> <span>(<i>impf</i>. ἀνεῖχον ; <i>f</i>. ἀνέξω <i>ou</i> ἀνασχήσω ; <i>ao.2</i> ἀνέσχον ; <i>pf</i>. ἀνέσχηκα, <i>etc</i>.)</span><br><b>A <i>tr</i>.<br>   I</b> (ἀνά, en haut) :<br><b>      1</b> lever : λαμπάδας ἀνασχεθεῖν, EUR. <i>Med. 1027,</i> porter (<i>litt</i>. lever) un flambeau ; χεῖρας, lever les mains (pour combattre, OD. <i>18, 89 ;</i> pour prier, IL. <i>3, 318 ;</i> pour s’avouer vaincu au pugilat, THCR. <i>Idyl. 22, 129, etc</i>.) ; τινὶ εὐχὰς ἀν. SOPH. <i>El. 636,</i> élever ses mains avec ses prières vers qqn ; χέρας ἄνεχε, ἄνεχε λόγον, EUR. <i>El. 592,</i> dirige vers le ciel tes mains, tes discours ; <i>p. suite,</i> lever pour offrir <i>ou</i> pour montrer : θεῷ τι ἀν. IL. <i>10, 460,</i> lever une offrande vers un dieu ; σκῆπτρον ἀν. θεοῖσι, IL. <i>7, 412,</i> lever son sceptre vers les dieux (pour les prendre à témoin) ; σημεῖον πυρὸς ἀν. THC. <i>4, 111,</i> lever un signal de feu ; φῶς ἀν. τινί, EUR. <i>Med. 482,</i> montrer à qqn une lueur (de salut) ; <i>avec un sujet de chose :</i> δάφνα ἀνέχει πτόρθους, EUR. <i>Hec. 458,</i> le laurier élève, <i>càd</i>. pousse ses rameaux ;<br><b>      2</b> tenir droit, tenir ferme, soutenir : οὐρανὸν καὶ γῆν, PAUS. <i>5, 11, 5,</i> le ciel et la terre, <i>en parl. d’Atlas ;</i> γέφυρα σκάφαις ἀνεχομένη, DH. <i>3, 55,</i> pont supporté par des barques, pont de bateaux ; <i>fig</i>. ἀν. εὐδικίας, OD. <i>19, 111,</i> soutenir <i>ou</i> maintenir le bon droit ; ἀν. Σικελίαν μὴ ὑπό τινα εἶναι, THC. <i>6, 86,</i> défendre la Sicile et la préserver d’être conquise ; <i>d’où</i> s’attacher à : ἀηδὼν ἀνέχουσα (<i>conj</i>. νέμουσα) κισσόν, SOPH. <i>O.C. 674,</i> le rossignol qui s’attache au lierre ;<br><b>   II</b> (ἀνά, en arrière) retenir, arrêter : ἵππους, IL. <i>23, 426,</i> retenir des chevaux ; ἑαυτὸν ἀν. ἀπό τινος, PLUT. <i>M. 514</i> a, se retenir de qqe ch. ;<br><b>B <i>intr</i>.<br>   I</b> (ἀνά, en haut) :<br><b>      1</b> s’élever, surgir : <i>particul</i>. sortir de l’eau, <i>en parl. d’Ulysse naufragé,</i> OD. <i>5, 320 ;</i> αἰχμὴ παρὰ ὦμον ἀνέσχεν, IL. <i>17, 310,</i> la javeline sortit par l’épaule ; <i>en parl. du soleil :</i> ἅμ' ἡλίῳ ἀνέχοντι, XÉN. <i>Cyn. 6, 13,</i> au soleil levant ; <i>cf</i>. EUB. (ATH. <i>8</i> c) ; PLAT. <i>Conv. 220</i> d (<i>cf</i>. ἀνίσχω) ; <i>p. anal</i>. se montrer, apparaître, SOPH. <i>Tr. 204 ; fig. en parl. d’événements,</i> se produire, arriver, HDT. <i>5, 106, etc. ;</i><br><b>      2</b> se dresser immobile, <i>en parl. de colonnes,</i> A. RH. <i>3, 217 ;</i><br><b>      3</b> faire saillie, s’avancer, <i>en parl. de pointes de terre qui s’avancent dans la mer,</i> HDT. <i>7, 123, etc. ;</i> THC. <i>1, 46, etc. ;</i><br><b>      4</b> se maintenir ferme, <i>d’où fig</i>. persévérer : <i>avec un part</i>. στέρξας ἀνέχει, SOPH. <i>Aj. 212 (var</i>. στέρξασαν ἔχει), il est constant dans son affection ; <i>cf</i>. THC. <i>7, 48 ; p. suite,</i> affirmer avec persistance, THC. <i>8, 94 ;</i> XÉN. <i>Hell. 2, 2, 10 ;</i><br><b>   II</b> (ἀνά, de nouveau) se relever : καμάτων, SOPH. <i>O.R. 174,</i> se relever, <i>càd</i>. être allégé de ses souffrances ;<br><b>   III</b> (ἀνά, en arrière) :<br><b>      1</b> se retenir, s’arrêter, cesser, THGN. <i>26 ; en parl. de choses (hémorrhoïdes,</i> HPC. <i>1147</i> e ; <i>pluie,</i> XÉN. <i>Hell. 1, 6, 28, etc</i>.) ; ἀν. τοῦ φονεύειν, PLUT. <i>Alex. 33,</i> cesser d’égorger ;<br><b>      2</b> <i>p. suite,</i> se tenir en repos, THC. <i>2, 18 ;</i><br><b><i>Moy</i>. ἀνέχομαι</b> <span>(<i>impf</i>. ἠνειχόμην ; <i>f</i>. ἀνέξομαι, <i>rar</i>. ἀνασχήσομαι ; <i>ao.2</i> ἠνεσχόμην, <i>rar</i>. ἀνεσχόμην)</span><br><b>   I <i>tr</i>.<br>      1</b> lever (qqe ch. à soi) : ἔγχος, IL. <i>5, 655,</i> lever sa javeline ; χεῖρας, OD. <i>18, 100,</i> lever les mains, <i>abs</i>. ἀνασχόμενος, IL. <i>3, 362, etc. ;</i> OD. <i>14, 425,</i> ayant levé les mains, les bras ;<br><b>      2</b> tenir droit, tenir ferme, <i>d’où</i> soutenir, supporter avec constance, <i>abs. impér</i>. ἀνάσχεο, IL. <i>1, 586,</i> supporte avec courage, prends courage ; <i>avec un acc. de</i> chose : ἀν. κήδεα, IL. <i>18, 430 ;</i> κακά, IL. <i>24, 518 ;</i> ESCHL. <i>Ag. 904 ;</i> AR. <i>Nub. 363,</i> supporter courageusement des malheurs, des maux ; ψύχη καὶ θάλπη, XÉN. <i>Hell. 5, 1, 15,</i> supporter le froid et le chaud ; <i>au mor</i>. τὴν δουλοσύνην, HDT. <i>1, 169 ; rar. avec un gén</i>. δουλοσύνης ἀν. OD. <i>22, 423,</i> se résigner à la servitude ; <i>cf</i>. PLAT. <i>Prot. 323</i> a ; DH. <i>8, 5 ; avec un acc. de pers</i>. ἀν. ξείνους, OD. <i>7, 32,</i> supporter des étrangers ; <i>avec un part. en accord avec le rég</i>. οὐκ ἀνέξομαί σε ἄλγε' ἔχοντα, IL. <i>5, 895,</i> je ne supporterai pas que tu aies à souffrir ; ἀνάσχου δέσποτας ὄντας, EUR. <i>Alc. 304,</i> souffre qu’ils soient les maîtres ; <i>cf</i>. OD. <i>19, 27 ;</i> SOPH. <i>Ant. 467, etc. ; qqf. avec le part. au gén</i>. ἀν. τινος λέγοντος, PLAT. <i>Rsp. 564</i> d, écouter patiemment qqn parler ; <i>avec un part. en accord avec le suj</i>. ἀνέχομαι κλύων, ESCHL. <i>Pers. 838 ;</i> ἀν. κλύουσα, SOPH. <i>El. 1028,</i> je supporte d’entendre, j’entends volontiers, <i>etc. ; rar. avec l’inf</i>. σὺν ἄλλοις βιοῦν οὐκ ἀν. EL. <i>N.A. 6, 30,</i> ne pouvoir supporter de vivre avec d’autres ; <i>cf</i>. HDT. <i>7, 139 ;</i> ARR. <i>An. 2, 17, 4 ; 5, 29, 1 ;</i> ALCIPHR. <i>3, 34 ;</i><br><b>   II <i>intr</i>.<br>      1</b> se lever, se tendre, <i>en parl. des mains elles-mêmes,</i> ARAT. <i>204 ;</i><br><b>      2</b> se soutenir, <i>en parl. d’un blessé,</i> IL. <i>5, 285 ;</i><br><b>      3</b> se contenir, IL. <i>23, 587</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act. prés. 3 sg. sbj. épq</i>. ἀνέχῃσι, OD. <i>19, 111 Bkk. Ao.2 épq</i>. ἀνέσχεθον, IL. <i>7, 412 ;</i> OD. <i>9, 294 ; inf. épq</i>. ἀνασχέμεν, IL. <i>24, 301. — Moy. fut. sync</i>. ἀνσχήσεσθαι, IL. <i>5, 114. Ao.2, 1 sg</i>. ἠνσχόμην, SOPH. <i>Ant. 467 ; 2 sg. poét</i>. ἀνάσχεο, IL. <i>1, 586 ; avec sync</i>. ἄνσχεο, IL. <i>24, 518 ; impér. 2 sg</i>. ἄνσχεο IL. <i>23, 587 ; 24, 549</i>.<br><span><b>Étym</b>. ἀνά, ἔχω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αν-εχομαι - ἀνέχω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n15 fois dans 14 versets de 11 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (5)</li>\n<li>Ephésiens (1)</li>\n<li>Colossiens (1)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>2 Timothée (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G431":"<h1>anepsios</h1>\n<p>Strong n° 431 <i>Prononciation [an-eps'-ee-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un cousin, fils de frère de parents, cousin germain</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀνεψιός, </b><b>οῦ (ὁ)</b> <span>[ᾰῐ]</span><br><b>      1</b> cousin germain (de père <i>ou</i> de mère), <i>d’où</i> cousin, IL. <i>9, 464 ;</i> HDT. <i>7, 5, etc. ;</i> THC. <i>1, 132 ;</i> ESCHL. <i>Pr. 856, etc. ; p. anal. en parl. de poissons,</i> STRATT. (ATH. <i>299</i> b) ;<br><b>      2</b> <i>postér</i>. neveu, PORPH.<br><span><b><span class=\"arrow\"></span></b> <span>[ῑ]</span> <i>dans</i> ἀνεψιοῦ, IL. <i>15, 554, et</i> ἀνεψιοῖο, Q. SM. <i>3, 295</i>.<br><span><b>Étym</b>. <i>p</i>. *ἀνεπτιός, <i>de</i> ἀ <i>cop. et</i> νεπ ; <i>cf. lat</i>. nĕpos.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ανεψιος - ἀνεψιός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G432":"<h1>anethon</h1>\n<p>Strong n° 432 <i>Prononciation [an'-ay-thon]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>anis, aneth\n<ol type=\"a\">\n<li>plante utilisée pour épices et médecine, genre de fenouil</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄνηθον, ου (τὸ)</b> <span>[ᾰ]</span> aneth, faux-anis, AR. <i>Nub. 982 ;</i> TH. <i>H.P. 7, 1, 2, etc. ;</i> GEOP. <i>12, 1, 2, etc</i>.<br><span><b>Étym</b>. <i>cf</i>. ἄνησον <i>et</i> ἄνητον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ανηθον - ἄνηθον</font>\n<br><br>probablement origine étrangère</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G433":"<h1>aneko</h1>\n<p>Strong n° 433 <i>Prononciation [an-ay'-ko]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être arrivé à, atteindre</li>\n<li>appartenir à ce qui est légal, ce qui est convenable, le devoir</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀν·ήκω :<br>A</b> (ἀνά, en haut) :<br><b>   I</b> être monté, s’être élevé : ἐς μέτρον, HDT. <i>2, 127,</i> jusqu’à une certaine mesure ; <i>fig</i>. χρήμασι ἀν. ἐς τὰ πρῶτα, HDT. <i>7, 134,</i> être parvenu au comble de la richesse ; ἐς τοῦτο θράσεος ἀν. HDT. <i>7, 9,</i> en être venu à ce degré d’audace ; ἐς τὰ μέγιστα ἀν. ἀρετῆς πέρι, HDT. <i>5, 49,</i> être parvenu, <i>d’où</i> être au plus haut degré de vertu ;<br><b>   II</b> s’élever, SOPH. <i>Tr. 1018 ; d’où p. ext. ou anal. :</i><br><b>      1</b> s’avancer : εἰς μεσόγαιαν, XÉN. <i>An. 6, 4, 5,</i> jusqu’au milieu des terres, <i>en parl. d’une chaîne de montagnes ; cf</i>. DS. <i>1, 31 ;</i><br><b>      2</b> <i>fig</i>. aboutir à : τοῦτο ἐς οὐδὲν ἀνήκει, HDT. <i>2, 104,</i> cela ne mène à rien, <i>càd</i>. ne prouve rien ;<br><b>      3</b> <i>p. suite,</i> se rattacher à, concerner (<i>lat</i>. pertinere ad) : ἀν. εἴς τινα, ANT. <i>123, 14,</i> concerner qqn ; ἀν. εἴς τι, DÉM. <i>1389, 21 ; 1390, 17 ; ou</i> πρός τι, POL. <i>2, 15, 4, etc. ;</i> DS. <i>1, 36, etc</i>. concerner qqe ch., avoir du rapport avec qqe ch. ; ἀνήκει ἔς σε ἔχειν, HDT. <i>6, 109,</i> il t’appartient d’avoir ;<br><b>      4</b> <i>p. ext</i>. convenir, être approprié à, NT. <i>Eph. 5, 4 ; Col. 3, 18 ;</i><br><b>B</b> (ἀνά, en arrière) revenir : εἰς τοὺς πρώτους λόγους, PLAT. <i>Theæt. 196</i> b, aux premiers discours.<br><span><b>Étym</b>. ἀνά, ἥκω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ανηκω - ἀνήκω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Ephésiens (1)</li>\n<li>Colossiens (1)</li>\n<li>Philémon (1)</li>\n</ul>\n</td></tr>\n</table>","G434":"<h1>anemeros</h1>\n<p>Strong n° 434 <i>Prononciation [an-ay'-mer-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>non apprivoisé, sauvage, féroce, cruel</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀν·ήμερος, ος, ον</b>, non apprivoisé, sauvage, <i>en parl. d’animaux,</i> ATH. <i>607</i> a ; <i>de personnes,</i> ESCHL. <i>Pr. 716 ;</i> ANACR. <i>1, 7 ;</i> DH. <i>1, 42 ;</i> LUC. <i>Phal. 1, 8 ; de plantes, de pays, etc</i>. ESCHL. <i>Eum. 14 ;</i> LUC. <i>Pr. 12 ; d’un genre de vie rude et grossier,</i> DH. <i>1, 41 ;</i> PLUT. <i>M. 86</i> d, <i>etc</i>.<br><span>•<i> Cp</i>. -ώτερος, ATH. <i>607</i> a.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. ἀνάμ- <span>[ᾱμ]</span> MOSCH. <i>1, 10</i>.<br><span><b>Étym</b>. ἀν-, ἥ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αν-ημερος - ἀνήμερος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT).\n<ul>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G435":"<h1>aner</h1>\n<p>Strong n° 435 <i>Prononciation [an'-ayr]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>En référence au sexe\n<ol type=\"a\">\n<li>Se dit d'un mâle</li>\n<li>d'un époux</li>\n<li>d'un fiancé ou futur marié</li>\n</ol>\n</li>\n<li>En référence à l'âge, pour distinguer un adulte homme d'un garçon</li>\n<li>Tout mâle</li>\n<li>D'une manière générique, dans un groupe l'ensemble hommes et femmes</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀνήρ (ὁ)</b> <span>[ᾰ, <i>mais v. ci-dessous</i>]</span> (<i>voc</i>. ἄνερ, <i>gén. etc</i>. ἀνδρός, ἀνδρί, ἄνδρα ; <i>pl</i>. ἄνδρες, ἀνδρῶν, ἀνδράσι, ἄνδρας ; <i>duel</i> ἄνδρε, ἀνδροῖν) <i>litt</i>. celui qui engendre, <i>d’où :</i><br><b>   I</b> mâle, <i>en parl. de personnes (hommes, enfants</i>) : ἀνδρῶν ἄπαις, PLAT. <i>Leg. 877</i> e, sans enfants mâles ; <i>en parl. d’animaux,</i> ARSTT. <i>H.A. 10, 6, 2 ; p. suite :</i><br><b>      1</b> homme, <i>p. opp. à femme,</i> IL. <i>17, 435 ;</i> OD. <i>21, 323, etc. ; au plur</i>. ἄνδρες γυναῖκες (<i>sans</i> καί) hommes et femmes, SOPH. <i>Ant. 1079 ;</i> AR. <i>Ran. 156 ;</i><br><b>      2</b> époux, mari, IL. <i>19, 291 ;</i> OD. <i>1, 292, etc. ;</i> HDT. <i>1, 146, etc. ;</i> εἰς ἀνδρὸς ὥραν ἥκειν, PLAT. <i>Criti. 113</i> d, être arrivée à l’âge de prendre un mari ; ἄνδρας ἀρτιζυγεῖς, ESCHL. <i>Pers. 542,</i> les époux récemment unis à elles ; <i>qqf</i>. amant, SOPH. <i>Tr. 551 ;</i> EUR. <i>Hipp. 491 ;</i> THCR. <i>Idyl. 15, 131 ; en parl. d’animaux,</i> THCR. <i>Idyl. 8, 49 (cf. lat</i>. vir gregis) ;<br><b>   II</b> homme :<br><b>      1</b> <i>p. opp. aux dieux (en ce sens, d’ord. au plur</i>.) : πατὴρ ἀνδρῶν τε θεῶν τε, HOM. père des hommes et des dieux ; <i>qqf. au sg</i>. IL. <i>13, 321 ; 18, 432, 433 ;</i> SOPH. <i>Aj. 77 ; souv. avec un adj. :</i> βροτὸς <i>ou</i> θνητὸς ἀ. HOM. un mortel ; ἄνδρες ἡμίθεοι, IL. <i>12, 23,</i> demi-dieux ; κατ' ἀνδρὸς βίοτον, EUR. <i>Hipp. 938,</i> de génération en génération ; <i>avec une nuance d’ironie :</i> τοῦ ποτε φίλων κυρεῖ τόδε πάλαιον ἀνδρὸς λείψανον ; EUR. <i>El. 553,</i> à quel ami appartient donc ce vieux débris d’homme ? ;<br><b>      2</b> homme fait, <i>p. opp. à jeune homme :</i> παῖς, μειράκιον, ἀνήρ, πρεσϐύτης, XÉN. <i>Conv. 4, 17,</i> enfant, jeune homme, homme fait, vieillard ; <i>de même, p. opp. à</i> παῖς, THC. <i>1, 115 ; à</i> παῖς <i>et à</i> μειράκιον, PLUT. <i>Alc. 1 ;</i> εἰς ἄνδρας ἐγγράφεσθαι, DÉM. <i>412, 25, ou</i> συντελεῖν, ISOCR. <i>277</i> b, être inscrit <i>ou</i> passer dans la classe des hommes faits ;<br><b>      3</b> homme, <i>avec l’idée de qualités morales ou extérieures ; au sens moral avec l’idée des qualités viriles (honneur, courage, vertu, etc</i>.) : ἀνέρες (<i>épq. p</i>. ἄνδρες) ἔστε, φίλοι, IL. <i>5, 529,</i> soyez hommes, amis ! πολλοὶ μὲν ἄνθρωποι, ὀλίγοι δὲ ἄνδρες, HDT. <i>7, 210,</i> beaucoup d’êtres humains, mais peu d’hommes ; <i>de même, p. opp. à</i> ἄνθρωπος, XÉN. <i>Hier. 7, 3 ; souv. en ce sens chez les Att. :</i> ἄνδρα γίγνεσθαί σε χρή, EUR. <i>El. 693,</i> il te faut être un homme ; εἰ ἄνδρες εἶεν οἱ στρατηγοί, THC. <i>4, 27,</i> si les généraux étaient des hommes ; Μενέλεως δ' ἐν ἀνδράσιν, EUR. <i>I.A. 945,</i> mais Ménélas compte parmi les hommes ; <i>cf</i>. XÉN. <i>Cyr. 4, 2, 25, etc. ;</i> PLAT. <i>Rsp. 359</i> b, <i>etc. ;</i><br><b>      4</b> <i>p. ext. joint aux titres ou professions :</i> ἀνὴρ βασιλεύς, HOM. roi ; ἀνὴρ μάντις, HDT. <i>6, 83,</i> devin ; ἀνὴρ νομεύς, SOPH. <i>O.R. 1118,</i> pâtre ; ἄνδρες δικασταί, ATT. juges, <i>etc. ; aux noms de peuples :</i> ἄνδρες Ἀθηναῖοι, ORAT. Athéniens ! <i>comiq</i>. ἄνδρες θεοί, LUC. <i>J. tr. 15,</i> messieurs les dieux ! ὦ ἄνδρες κύνες, ATH. <i>160</i> b, messieurs les chiens ! ;<br><b>      5</b> <i>p. ext</i>. homme, individu : ὁ ἀν. PLAT. <i>Phæd. 57</i> a, <i>etc</i>. l’homme, <i>c. synon. de</i> αὐτός <i>ou</i> ἐκεῖνος, celui-ci, celui-là ; πᾶς ἀνήρ, PLAT. <i>Leg. 736</i> c, <i>etc</i>. tout homme, chaque homme ; κατ' ἄνδρα, ISOCR. <i>271</i> a, homme par homme ; <i>particul. en parl. de combattants,</i> IL. <i>15, 328 ;</i> ESCHL. <i>Sept. 346 ; de prisonniers qu’on échange,</i> THC. <i>2, 103 ; en gén. de soldats,</i> THC. <i>1, 107 ; 7, 43 et 76, etc. ;</i> XÉN. <i>An. 4, 8, 4, etc. ;</i> simple particulier, <i>p. opp. à homme d’État,</i> XÉN. <i>An. 1, 9, 8</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Par crase att</i>. ὁ ἀνήρ devient ἁνήρ, XÉN. <i>Cyr. 2, 2, 29 ; ion</i>. ὡνήρ, HDT. <i>4, 161 ;</i> τοῦ ἀνδρός = τἀνδρός, XÉN. <i>Hell. 3, 1, 12 ;</i> PLAT. <i>Lach. 179</i> e, <i>181</i> a ; <i>Soph. 221</i> d ; τῷ ἀνδρί = τἀνδρί, SOPH. <i>Tr. 60, 603, etc. ;</i> PLUT. <i>M. 775</i> c, <i>etc. ;</i> οἱ ἄνδρες = ἅνδρες, <i>ion</i>. ὧνδρες, HDT. <i>4, 134. Décl. épq. : voc</i>. ἆνερ ; <i>gén. et dat</i>. ἀνέρος, ἀνέρι ; <i>pl</i>. ἀνέρες, <i>etc. ; dat</i>. ἄνδρεσσι, OD. <i>1, 358, etc. Chez les Épq</i>. <span>[ᾱ]</span> <i>dans</i> ἀνήρ <i>à l’arsis, et dans les formes trisyll</i>. ἀνέρος, <i>etc., qqf. chez les Trag. (chœurs</i>) SOPH. <i>O.R. 869, Tr. 1010</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *h₂ner-, homme ; <i>cf. sscr</i>. nā́, nár-, <i>lat</i>. Nerō.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ανερ - ἀνήρ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n214 fois dans 192 versets de 16 livres bibliques (NT)\n<ul>\n<li>Matthieu (8)</li>\n<li>Marc (4)</li>\n<li>Luc (26)</li>\n<li>Jean (8)</li>\n<li>Actes (99)</li>\n<li>Romains (9)</li>\n<li>1 Corinthiens (32)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (1)</li>\n<li>Ephésiens (7)</li>\n<li>Colossiens (2)</li>\n<li>1 Timothée (5)</li>\n<li>Tite (2)</li>\n<li>Jacques (6)</li>\n<li>1 Pierre (3)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G436":"<h1>anthistemi</h1>\n<p>Strong n° 436 <i>Prononciation [anth-is'-tay-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>être contre, supporter, résister, s'opposer, résister à</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀνθ·ίστημι</b> <span>(<i>f</i>. ἀντιστήσω, <i>ao</i>. ἀντέστησα, <i>pf</i>. ἀνθέστηκα, <i>etc</i>.)</span><br><b>   I <i>tr</i>.<br>      1</b> placer en face <i>ou</i> contre : τινά τινι ἀ. PLAT. <i>Leg. 834</i> a, opposer une personne à une autre (pour une lutte) ; ἀ. τρόπαιον, THC. <i>1, 54,</i> élever un trophée en face <i>ou</i> à l’encontre d’un autre ;<br><b>      2</b> mettre en parallèle, comparer avec, PLUT. <i>Thes. 1 ;</i><br><b>   II</b> <i>intr. (à l’ao.2</i> ἀντέστην, <i>au pf., au pl. q. f. et au moy</i>.) :<br><b>      1</b> se placer en face de, <i>d’où</i> s’opposer à, résister à : τινί, à qqn, IL. <i>20, 70, etc. ;</i> HDT. <i>6, 117, etc. ;</i> DÉM. <i>127, 5, etc. ; ou</i> πρός τινα, THC. <i>1, 93 ;</i> XÉN. <i>Conv. 5, 1,</i> à qqn ; <i>avec un rég. de chose :</i> τινί, PLAT. <i>Leg. 732</i> c ; DÉM. <i>1479, 15,</i> à qqe ch. ; ὑπέρ τινος, lutter pour qqn, DÉM. <i>127, 5 ; ou</i> pour qqe ch. SOPH. <i>Aj. 1231, Ant. 518 ; abs</i>. IL. <i>16, 305 ;</i> HDT. <i>8, 91 ;</i> THC. <i>1, 41 ;</i> XÉN. <i>Cyr. 2, 4, 23, etc. ;</i><br><b>      2</b> <i>en parl. de choses,</i> tourner à l’encontre, tourner défavorablement, THC. <i>5, 4 ;</i> DÉM. <i>450, 15</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Part. pf. act</i>. ἀνθεστώς, THC. <i>6, 70. Ion</i>. ἀντίστημι, HDT. <i>8, 91</i>.<br><span><b>Étym</b>. ἀντί, ἵ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ανθ-ιστημι - ἀνθίστημι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n14 fois dans 12 versets de 9 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n<li>Actes (2)</li>\n<li>Romains (3)</li>\n<li>Galates (1)</li>\n<li>Ephésiens (1)</li>\n<li>2 Timothée (3)</li>\n<li>Jacques (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G437":"<h1>anthomologeomai</h1>\n<p>Strong n° 437 <i>Prononciation [anth-om-ol-og-eh'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>répondre en professant ou confessant</li>\n<li>faire un accord, agrément mutuel</li>\n<li>reconnaître, remercier, louer</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀνθ·ομολογέομαι-οῦμαι :<br>      1</b> faire une convention mutuelle : πρός τινα, DÉM. <i>894, 26 ;</i> POL. <i>5, 56, 4 ; ou</i> τινι, POL. <i>10, 45, 10,</i> avec qqn ; <i>t. de droit att</i>. faire novation par substitution de créancier, ORAT. ;<br><b>      2</b> tomber d’accord, convenir, reconnaître : τὰς ἀρετάς τινος, DS. <i>1, 70,</i> les vertus <i>ou</i> les mérites de qqn ; ἁμαρτίας, JOS. <i>A.J. 8, 10, 3,</i> avouer ses torts ; χάριν, PLUT. <i>Æmil. 11,</i> témoigner publiquement sa reconnaissance ; <i>d’où abs</i>. rendre grâces à Dieu, SPT. <i>1Esdr. 8, 88 ; Ps. 78, 13 ; 3 Macc. 6, 33 ;</i> NT. <i>Luc. 2, 38</i>.<br><span><b>Étym</b>. ἀντί, ὁ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ανθ-ομολογεομαι - ἀνθομολογέομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G438":"<h1>anthos</h1>\n<p>Strong n° 438 <i>Prononciation [anth'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une fleur</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n①<b>ἄνθος, </b><b>εος-ους (τὸ) :<br>   I</b> ce qui croît, ce qui pousse, une pousse, OD. <i>9, 449 ;</i><br><b>   II</b> <i>particul</i>. fleur :<br><b>      1</b> <i>au propre,</i> IL. <i>2, 89, etc. ;</i> OD. <i>6, 231, etc. ;</i> HÉS. <i>O. 75, etc. ;</i> ATT. (PLAT. <i>Phæd. 110</i> d, <i>etc</i>.) ;<br><b>      2</b> <i>fig</i>. ἥϐης ἄ. IL. <i>13, 484 ;</i> ὥρας ἄ. XÉN. <i>Conv. 8, 14 ;</i> ἄνθος παιδείης, THGN. <i>1305, 1348,</i> la fleur de la jeunesse ; ἀ. Ἀργείων, ESCHL. <i>Ag. 197 ;</i> ἄνθος Περσίδος αἴας, ESCHL. <i>Pers. 59 ;</i> Ἑλλάδος ἄνθος, EUR. <i>Tr. 807,</i> la fleur des Argiens, de la Perse, de la Grèce, <i>càd</i>. les plus vaillants, les plus nobles ; τὰ ἄνθη, A. PL. <i>274 ;</i> CIC. <i>Att. 16, 11, 1,</i> fleurs de poésie, <i>càd</i>. pièces choisies, anthologie ; <i>p. suite,</i> ce qui est dans son plein épanouissement : ἄ. ἔρωτος, ESCHL. <i>Ag. 744,</i> un amour dans toute sa fraîcheur <i>ou</i> dans toute sa force ; <i>cf</i>. SOPH. <i>Tr. 1000 ;</i><br><b>      3</b> <i>p. ext</i>. couleur brillante, éclat (de l’or, THGN. <i>452 ;</i> des couleurs et des broderies sur un vêtement, PLAT. <i>Rsp. 557</i> c) ; <i>particul</i>. éclat de la pourpre, PLAT. <i>Rsp. 429</i> d ; ARSTT. <i>H.A. 5, 15, 6 ;</i><br><b>      4</b> efflorescence : ἁλὸς ἄνθος, DIOSC. <i>5, 128,</i> fleur du sel, salpêtre ; προσώπου ἄνθη, HPC. <i>Coac. 185,</i> efflorescences du visage (<i>cf</i>. ἐξάνθημα) ; <i>abs</i>. ἄνθος, fleur de pourpre, <i>teinture,</i> TH. <i>Od. 5, 22</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Les Att. (sel</i>. TH. MAG. <i>p. 73 ;</i> ANTIATT. <i>p. 83, 12 Bkk. ;</i> EM. <i>v°</i> ἀνθ' ὧν, <i>etc.) ne contractent pas d’ord. le gén. plur</i>. ἀνθέων, <i>pour éviter la confusion avec</i> ἀνθῶν, <i>part. prés., et avec</i> ἀνθ' ὧν ; <i>ttef</i>. ἀνθῶν <i>dans</i> XÉN. <i>Cyn. 5, 5 ;</i> PLAT. <i>Criti. 115</i> a.<br><span><b>Étym</b>. <i>p.-ê. R. indo-europ</i>. *h₂end<sup>h</sup>-, pousse, <i>cf. sscr</i>. ándhas-, plante du soma.</span><br><br>\n②<b>ἄνθος, ου (ὁ)</b> bruant, <i>ou p.-ê</i>. bergeronnette jaune, <i>oiseau,</i> ARSTT. <i>H.A. 8, 3, 5</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ανθος - ἄνθος</font>\n<br><br>mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Jacques (2)</li>\n<li>1 Pierre (2)</li>\n</ul>\n</td></tr>\n</table>","G439":"<h1>anthrakia</h1>\n<p>Strong n° 439 <i>Prononciation [anth-rak-ee-ah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un tas de charbons allumés, feu de braises, braséro (de charbon de bois)</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀνθρακιά, ᾶς (ἡ)</b> <span>[ᾰκ]</span><br><b>      1</b> brasier de charbon, IL. <i>9, 213 ;</i> HH. <i>Merc. 140 ;</i> EUR. <i>Cycl. 358 ;</i> AR. <i>Eq. 780, etc. ;</i> τιθέναι τινὰ ἐπὶ ἀνθρακιῇ, ANTH. <i>12, 17, ou</i> τίθεσθαί τινα ἀνθρακιήν, ANTH. <i>12, 166,</i> mettre qqn sur les charbons, lui faire désirer vivement qqe ch. ;<br><b>      2</b> four à charbon, fourneau, ANTH. <i>11, 166</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. -ίη, IL. HH. ANTH. <i>ll. cc</i>.<br><span><b>Étym</b>. ἄνθραξ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ανθρακια - ἀνθρακιά</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Jean (2)</li>\n</ul>\n</td></tr>\n</table>","G440":"<h1>anthrax</h1>\n<p>Strong n° 440 <i>Prononciation [anth'-rax]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>charbons en feu ou en braise, charbons ardents</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄνθραξ, ακος (ὁ)</b> <span>[ᾰκ]</span><br><b>      1</b> charbon, <i>en ce sens, rar. au sg</i>. EUR. <i>Cycl. 245 ;</i> ARÉT. <i>p. 7, 34 ; d’ord. au plur</i>. THC. <i>4, 100 ;</i> AR. <i>Ach. 34, etc. ;</i><br><b>      2</b> escarboucle, <i>pierre précieuse,</i> ARSTT. <i>Meteor. 4, 9, 30 ;</i> TH. <i>Lap. 8, 16, etc. ;</i> JOS. <i>A.J. 3, 7, 5 ;</i><br><b>      3</b> charbon, <i>ulcère,</i> HPC. <i>1075</i> h ; P. EG. <i>4, 25</i>.<br><span><b>Étym</b>. <i>pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ανθραξ - ἄνθραξ</font>\n<br><br>dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G441":"<h1>anthropareskos</h1>\n<p>Strong n° 441 <i>Prononciation [anth-ro-par'-es-kos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>étudier pour plaire aux hommes, chercher leur faveur</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀνθρωπ·άρεσκος, ος, ον</b> <span>[ᾰρ]</span> qui veut plaire aux hommes, qui professe le respect humain, NT. <i>Eph. 6, 6 ; Col. 3, 22</i>.<br><span><b>Étym</b>. ἄνθρωπος, ἀρέσκω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αντρωπ-αρεσκος - ἀνθρωπάρεσκος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Ephésiens (1)</li>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G442":"<h1>anthropinos</h1>\n<p>Strong n° 442 <i>Prononciation [anth-ro'-pee-nos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>humain\n<ol type=\"a\">\n<li>appliqué à ce qui appartient aux hommes</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀνθρώπινος, η, ον</b>, d’homme, humain, <i>càd. :</i><br><b>      1</b> qui concerne l’homme : βίος ἀνθρ. HDT. <i>7, 46,</i> la vie humaine ; τὸ ἀνθρ. γένος, PLAT. <i>Phæd. 82</i> b ; ANT. <i>125, 22, ou abs</i>. τὸ ἀνθρώπινον, HDT. <i>1, 86,</i> le genre humain ; τὰ ἀνθρ. πράγματα, PLAT. <i>Parm. 134</i> e, <i>ou abs</i>. τἀνθρώπινα, PLAT. <i>Theæt. 170</i> b, les affaires humaines ;<br><b>      2</b> qui provient de l’homme : ἀνθρ.τεκμήρια, ANT. <i>139, 1,</i> preuves fournies par les hommes, <i>p. opp. aux présages ;</i><br><b>      3</b> qui convient à l’homme, propre à l’homme : φύσις ἀνθρ. PLAT. <i>Tim. 90</i> c, nature humaine ; ἀνθρ. σοφία, XÉN. <i>Cyr. 1, 6, 46,</i> sagesse humaine ; ἀνθρ. ἀμαθία, PLAT. <i>Leg. 737</i> b, ignorance humaine ; ἀνθρώπινα φρονεῖν ἄνθρωπον ὄντα, ARSTT. <i>Nic. 10, 8,</i> avoir, étant homme, des sentiments humains ;<br><b>      4</b> <i>p. suite,</i> médiocre, petit, NT. <i>Rom. 6, 19 ;</i> CHRYS. <i>9, 542 Migne</i>.<br><span>•<i> Cp</i>. -ώτερος, LUC. <i>D. mort. 10, 9</i>.<br><span><b>Étym</b>. ἄνθρωπος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ανθρωπινος - ἀνθρώπινος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 4 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>1 Corinthiens (4)</li>\n<li>Jacques (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G443":"<h1>anthropoktonos</h1>\n<p>Strong n° 443 <i>Prononciation [anth-ro-pok-ton'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un meurtrier</li>\n<li>le dictionnaire Grec « Bailly » donne cette définition: qui consiste en êtres humains tués (nourriture)</li>\n<li>ce mot est composé de ανθρωπος qui signifie, homme, être humain et de κτονος qui vient du verbe κτεινω qui signifie : tuer, mener à la mort.</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n①<b>ἀνθρωπο·κτόνος, ος, ον</b>, homicide (<i>personne</i>) EUR. <i>I.T. 389</i>.<br><span><b>Étym</b>. ἄ. κτείνω.</span><br><br>\n&#x2461<b>ἀνθρωπό·κτονος, ος, ον</b>, qui consiste en êtres humains tués (<i>nourriture</i>) EUR. <i>Cycl. 127</i>.<br><span><b>Étym</b>. ἄ. κτείνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ανθρωπο-κτονος - ἀνθρωποκτόνος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> n'importe quel « meurtrier », — dont le mot , « brigand, assassin », est un des types ; tandis que  dans le NT contient une certaine emphase.</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Jean (1)</li>\n<li>1 Jean (2)</li>\n</ul>\n</td></tr>\n</table>","G444":"<h1>anthropos</h1>\n<p>Strong n° 444 <i>Prononciation [anth'-ro-pos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un être humain, homme ou femme\n<ol type=\"a\">\n<li>d'une façon générique, tous les individus</li>\n<li>distinction de l'homme par rapport à d'autres éléments\n<ol>\n<li>animaux ou plantes</li>\n<li>ce qui vient de Dieu ou Christ</li>\n<li>des anges</li>\n</ol>\n</li>\n<li>avec en complément la notion de faiblesse, qui conduit l'homme à la faute et au péché</li>\n<li>avec adjonction de notion de mépris ou de dédain</li>\n<li>avec référence aux deux natures de l'homme, corps et esprit</li>\n<li>référence à l'homme corrompu et à celui conforme à la nature de Dieu, c'est à dire le véritable homme de Christ</li>\n<li>en référence au sexe : le mâle</li>\n</ol>\n</li>\n<li>indéfini : quelqu'un, un homme</li>\n<li>pluriel : gens</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄνθρωπος, ου (ὁ</b> <i>et</i> <b>ἡ) :<br>   I</b> ὁ ἄνθρωπος, homme :<br><b>      1</b> <i>p. opp. aux dieux,</i> IL. <i>5, 442 ;</i><br><b>      2</b> <i>p. opp. à</i> ἀνήρ ;<br><b>      3</b> <i>p. opp. à</i> γυνή, IL. <i>9, 134 ;</i> ESCHN. <i>76, 4 ;</i> PLUT. <i>Cleom. 37 ;</i><br><b>      4</b> <i>en gén</i>. homme, être humain : ὁ ἄνθρ. THC. <i>1, 140 ;</i> PLAT. <i>Prot. 321</i> b ; <i>ou sans art</i>. ἄνθρωπος, XÉN. <i>Hipp. 4, 20 ;</i> PLAT. <i>Rsp. 603</i> c, <i>etc</i>. l’homme ; <i>de même au plur</i>. οἱ ἄνθρωποι <i>ou</i> ἄνθρωποι, PLAT. <i>Prot. 317</i> b, les hommes ; <i>avec un part</i>. ὤν <i>ou</i> πεφυκώς : ἄνθρωπον ὄντα, ἀνθρώπῳ πεφυκότι, ἀνθρώπους ὄντας, étant né homme, étant homme, <i>càd</i>. attendu qu’on est homme, puisqu’on est homme : πῶς οὐκ ἄνθρωπόν γε ὄντα εἰκὸς σοφώτερον τούτων φαίνεσθαι ; XÉN. <i>Hipp. 4, 20,</i> comment ne serait-il pas naturel que l’homme (<i>litt</i>. par cela même qu’il est homme) se montrât plus intelligent que ces (bêtes) ? <i>de même,</i> ἀνθρώπῳ πεφυκότι, XÉN. <i>Cyr. 1, 1, 3 ;</i> ἀνθρώπους ὄντας, POL. <i>2, 4, 5 ;</i> κατ' ἄνθρωπον, ESCHL. <i>Sept. 425 ;</i> SOPH. <i>O.C. 598 ;</i> DS. <i>1, 31, etc. ;</i> κατ' ἀνθρώπους, DC. <i>53, 16,</i> comme il convient à l’homme, comme il est habituel à l’homme, selon la nature humaine ; ὑπὲρ ἄνθρωπον, DC. <i>13, 21, etc</i>. au-dessus de l’homme, au-dessus des forces humaines ; <i>particul. au plur. dans les loc</i>. ἐν ἀνθρώποις, ἐξ ἀνθρώπων, <i>etc</i>. d’entre les hommes : δεινότατος τῶν ἐν ἀνθρώποις, DÉM. <i>1246, 13,</i> le meilleur homme du monde ; ὁ ἄριστος ἐν ἀνθρώποις ὄρτυξ, PLAT. <i>Lys. 211</i> e, la meilleure caille du monde ; τὰ ἐξ ἀνθρώπων πράγματα, PLAT. <i>Theæt. 170</i> e, toutes les affaires du monde, <i>càd</i>. tous les embarras possibles ; μάλιστα ἀνθρώπων, HDT. <i>1, 60,</i> plus que nul autre d’entre les hommes ; ἄριστά γ' ἀνθρώπων, PLAT. <i>Theæt. 148</i> b, le mieux du monde ; ἥκιστα ἀνθρώπων, PLAT. <i>Prot. 361</i> e, <i>Phæd. 67</i> e, pas le moins du monde ; <i>joint à un subst</i>. ἄνθρ. ὁδίτης, IL. <i>16, 263,</i> un voyageur ; ἄνθρ. βασιλεύς, NT. <i>Matth. 22, 2,</i> un roi ; <i>ou à un n. de peuple :</i> πόλις Μερόπων ἀνθρώπων, HH. <i>Ap. 42,</i> la ville des Méropes ; <i>mais, ainsi construit, souv. avec un sens de mépris chez les Att. :</i> ἄνθρωπος ὑπογραμματεύς, LYS. <i>186, 6,</i> un misérable scribe en sous-ordre ; γόης ἄνθρωπος, ESCHN. <i>48, 32,</i> un misérable charlatan, <i>etc. ;</i> ἄνθρωπος <i>qqf. seul en ce sens,</i> PLAT. <i>Phæd. 117</i> e, <i>etc. ;</i> DÉM. <i>543, 26 ;</i><br><b>   II</b> ἡ ἄνθρωπος, femme, HDT. <i>1, 60 ;</i> ISOCR. <i>381</i> b ; ARSTT. <i>Nic. 7, 5, 2 ;</i> PLUT. <i>Alc. 23 ; avec un sens de pitié ou de mépris,</i> DÉM. <i>402, 24 ;</i> THCR. <i>Idyl. 15, 89 ; particul. au voc. avec idée de colère ou d’impatience,</i> THCR. <i>Idyl. 15, 71 ; ou de mépris,</i> THCR. <i>Idyl. 4, 62 ; particul</i>. femme esclave, servante, ANT. <i>113, 17 ;</i> LYS. <i>9, 7 ; 93, 8 ; 98, 9 ;</i> IS. <i>58, 20</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Par crase att</i>. ὁ ἄνθρωπος <i>devient</i> ἅνθρωπος, <i>dor. et ion</i>. ὥνθρωπος, THCR. <i>Idyl. 4, 62 ; 15, 71, 83, 89, etc</i>.<br><span><b>Étym</b>. <i>probabl. pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ανθρωπος - ἄνθρωπος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n557 fois dans 503 versets de 24 livres bibliques (NT)\n<ul>\n<li>Matthieu (116)</li>\n<li>Marc (55)</li>\n<li>Luc (101)</li>\n<li>Jean (59)</li>\n<li>Actes (46)</li>\n<li>Romains (27)</li>\n<li>1 Corinthiens (30)</li>\n<li>2 Corinthiens (8)</li>\n<li>Galates (15)</li>\n<li>Ephésiens (9)</li>\n<li>Philippiens (3)</li>\n<li>Colossiens (7)</li>\n<li>1 Thessaloniciens (5)</li>\n<li>2 Thessaloniciens (2)</li>\n<li>1 Timothée (10)</li>\n<li>2 Timothée (5)</li>\n<li>Tite (5)</li>\n<li>Hébreux (10)</li>\n<li>Jacques (7)</li>\n<li>1 Pierre (6)</li>\n<li>2 Pierre (4)</li>\n<li>1 Jean (1)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (25)</li>\n</ul>\n</td></tr>\n</table>","G445":"<h1>anthupateuo</h1>\n<p>Strong n° 445 <i>Prononciation [anth-oo-pat-yoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>être proconsul, député</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀνθυπατεύω</b> <span>[ῠᾰ]</span> être proconsul, PLUT. <i>Dem. c. Cic. 3 ;</i> HDN <i>7, 5</i>.<br><span><b>Étym</b>. ἀνθύπατος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ανθυπατευω - ἀνθυπατεύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G446":"<h1>anthupatos</h1>\n<p>Strong n° 446 <i>Prononciation [anth-oo'-pat-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un proconsul\n<ol type=\"a\">\n<li>l'empereur Auguste avait divisé les provinces Romaines en sénatoriales et impériales. Les premières étaient dirigées par des proconsuls, les autres par des légats de l'empereur, qui étaient appelés « propraetor », propréteurs</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀνθ·ύπατος, ος, ον</b> <span>[ῠᾰ]</span><br><b>      1</b> proconsulaire, DH. <i>9, 16 ; 11, 62 ;</i><br><b>      2</b> ὁ ἀ. proconsul, POL. <i>21, 8, 11 ;</i> DH. <i>9, 16 ;</i> PLUT. <i>Galb. 3, etc</i>.<br><span><b>Étym</b>. ἀντί, ὕ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ανθυπατος - ἀνθύπατος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (4)</li>\n</ul>\n</td></tr>\n</table>","G447":"<h1>aniemi</h1>\n<p>Strong n° 447 <i>Prononciation [an-ee'-ay-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>renvoyer, relâcher, desserrer</li>\n<li>renoncer à, omettre, calmer</li>\n<li>laisser, ne pas soutenir, laisser enfoncer</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀν·ίημι</b> <span>(<i>impf</i>. ἀνίην, <i>f</i>. ἀνήσω, <i>ao</i>. ἀνῆκα, <i>pf</i>. ἀνεῖκα ; <i>pass</i>. ἀνίεμαι, <i>f</i>. ἀνεθήσομαι, <i>ao</i>. ἀνείθην, <i>d’où part</i>. ἀνεθείς, <i>pf</i>. ἀνεῖμαι)</span> <span>[ῐ, <i>mais v. fin de l’article</i>]</span><br><b>   I <i>tr.</i></b> envoyer <i>ou</i> lancer en haut, <i>d’où :</i><br><b>      1</b> faire sourdre, faire jaillir : κρήνην, EUR. <i>Bacch. 766 ;</i> φλόγα, THC. <i>2, 77,</i> une source, une flamme ; πνεῦμα, EUR. <i>Or. 277,</i> lancer un souffle ; <i>p. suite,</i> produire : καρπόν, HH. <i>Cer. 333 ;</i> TH. <i>C.P. 5, 1, 5,</i> un fruit ; μηδὲν ὧν ἡ γῆ ἀνίησι, XÉN. <i>Cyn. 6, 25,</i> rien de ce que la terre produit ;<br><b>      2</b> faire monter, faire remonter (d’une prison souterraine, SOPH. <i>Ant. 1101 ;</i> des enfers, ESCHL. <i>Pers. 650, etc</i>.) ;<br><b>      3</b> laisser monter dans, donner accès en haut : τινά, XÉN. <i>Hell. 2, 4, 11,</i> à qqn ;<br><b>      4</b> faire saillir, mettre en saillie ; <i>d’où part. pf. pass</i>. ἀνειμένος, η, ον, qui est en saillie : ἀνειμένον (τόρμιον) ἐκ τῆς διώστρας, PHIL. BYZ. bouton en saillie sur le tiroir ;<br><b>      5</b> lâcher, lancer : κύνας, XÉN. <i>Cyn. 7, 7,</i> lâcher des chiens ; <i>d’où</i> exciter, <i>en parl. de désir, de colère, de passions,</i> IL. <i>7, 25, etc. ;</i> Μοῦσ' ἀοιδὸν ἀνῆκεν ἀειδέμεναι, OD. <i>8, 73,</i> la Muse a poussé le chantre à chanter ;<br><b>      6</b> laisser aller, lâcher : δεσμῶν, OD. <i>8, 359,</i> délivrer (qqn) de ses liens ; πύλας, IL. <i>21, 537,</i> ouvrir les portes ; ἵππον, SOPH. <i>El. 721,</i> laisser aller un cheval, lui relâcher les rênes ; ἵππους εἰς τάχος ἀν. XÉN. <i>Hipp. 3, 2,</i> laisser aller des chevaux à une allure rapide ; <i>fig</i>. τῷ δήμῳ τὰς ἡνίας ἀν. PLUT. <i>Per. 11,</i> lâcher la bride au peuple ; <i>d’où</i> ἐλαύνειν ἀνέντα, XÉN. <i>Hell. 2, 4, 22,</i> chevaucher en laissant aller son cheval ;<br><b>      7</b> <i>p. suite,</i> permettre, <i>avec une prop. inf. :</i> ἀν. τρίχας αὔξεσθαι, HDT. <i>2, 36,</i> laisser croître les cheveux ; ἀν. τινὰ ὅ τι βούλεται ποιεῖν, PLAT. <i>Lach. 179</i> a, laisser qqn faire à sa guise ; <i>rar. avec le dat. de pers</i>. ἀνεὶς αὐτῷ θηρᾶν, XÉN. <i>Cyr. 4, 6, 3,</i> lui ayant permis de chasser ;<br><b>      8</b> relâcher, détendre (<i>p. opp. à</i> ἐντείνω <i>ou</i> ἐπιτείνω) : ἀν. φυλακήν, THC. <i>4, 27,</i> τὴν τῆς ἀρετῆς ἄσκησιν, XÉN. <i>Cyr. 7, 5, 70,</i> se relâcher d’une garde, de la pratique de la vertu ; ἀν. τινὶ θάνατον, EUR. <i>Andr. 532,</i> faire remise à qqn de la peine de mort ; ἀν. τὰ χρέα, PLUT. <i>Sol. 15,</i> faire remise des dettes ; ἀν. τινὸς ἔχθραν, THC. <i>3, 10,</i> se relâcher de sa haine contre qqn ; ἀν. ἀρχήν, πόλεμον, THC. <i>1, 76 ; 7, 18,</i> laisser échapper l’hégémonie, laisser languir la guerre ; <i>au part. pf. pass</i>. ἀνειμένος, η, ον (<i>cp</i>. -ώτερος, JAMBL. <i>V. Pyth. 54</i>) relâché ; <i>abs. joint à</i> μαλακός : ὀσμὴ μαλακὴ καὶ ἀνειμένη, TH. <i>C.P. 5, 7, 1,</i> odeur douce et sans âcreté ; ἀνειμένος καὶ μαλακὸς ἀήρ, TH. <i>C.P. 5, 4, 4,</i> air tiède et doux ; <i>avec une prép. :</i> ἡδοναὶ ἀνειμέναι, PLAT. <i>Rsp. 573</i> a, plaisirs licencieux ; δίαιτα ἀνειμένη, THC. <i>1, 6,</i> genre de vie facile ; ἀνειμένος ἐς τὸ ἐλεύθερον, HDT. <i>7, 103 ;</i> εἰς τὸ κέρδος, EUR. <i>Her. 3 ; ou avec</i> πρός : πρὸς τρυφάς, PLUT. <i>Demetr. c</i>. ANT. <i>3,</i> qui s’abandonne à l’amour de la liberté, au désir du gain, à la mollesse ; <i>avec</i> ἐπί : ἐπὶ τὸ λευκότερον, PTOL. <i>Geogr. 8, 29, 31</i> (couleur) qui se dégrade en une teinte plus pâle ; <i>abs</i>. ἀνειμένη τάσις, PORPH. <i>Pros. 103,</i> l’accent grave (<i>litt</i>. relâché, <i>p. opp. à l’accent aigu) ; abs</i>. laisser se reposer (une terre, un animal) ISOCR. <i>302</i> c ; TH. <i>H.P. 8, 11, 9 ; en parl. d’emplacements ou d’animaux consacrés :</i> ἀνιέναι ἀργὸν χωρίον θεῷ, PLUT. <i>Popl. 8,</i> laisser un emplacement inculte pour un dieu, <i>càd</i>. le consacrer à un dieu ; <i>abs</i>. THC. <i>4, 116 ; p. suite, au pass</i>. être consacré : ἄλσος ἀνειμένον, PLAT. <i>Leg. 761</i> c, bois consacré ; <i>en parl. d’animaux,</i> HDT. <i>2, 65, et, p. ext., de pers</i>. SOPH. <i>Aj. 1214 ; cf</i>. EUR. <i>Ph. 947 ;</i><br><b>   II <i>intr.</i></b> se relâcher : ἀνίει τὰ πνεύματα, HDT. <i>2, 113,</i> le vent tombait ; <i>cf</i>. SOPH. <i>Ph. 639 ;</i> αἱ τιμαὶ ἀνείκασι, DÉM. <i>1290, 22,</i> les prix sont baissés ; <i>avec un gén</i>. ἀν. ὀργῆς, AR. <i>Ran. 700 ;</i> DÉM. <i>572, 2,</i> se relâcher de sa colère ; <i>cf</i>. THC. <i>5, 32 ;</i> EUR. <i>Med. 456, etc. ; avec un part</i>. ὕων οὐκ ἀνίει (ὁ θεός) HDT. <i>4, 28,</i> il ne cesse de pleuvoir ; οὐκ ἀνῆκεν ἐνενήκοντα στάδια διώκων, XÉN. <i>Hell. 5, 3, 2,</i> il ne cessa pas de (les) poursuivre pendant 90 stades ;<br><b><i>Moy.</i></b> <span>(<i>f</i>. ἀνήσομαι)</span><br><b>      1</b> mettre à découvert sur soi ; κόλπον ἀνιεμένη, IL. <i>22, 80,</i> découvrant son sein ;<br><b>      2</b> <i>p. suite,</i> écorcher : αἶγας ἀνιέμενοι, OD. <i>2, 300,</i> écorchant des chèvres ; <i>cf</i>. EUR. <i>El. 826</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. 2 sg. poét</i>. ἀνιεῖς, IL. <i>5, 880 ; 3 pl. ion</i>. ἀνιεῖσι, HDT. <i>2, 36 ; att</i>. ἀνιᾶσι, THC. <i>6, 86. Impf. 1 sg</i>. ἀνίειν, LUC. <i>Cat. 4 (2 et 3 sg. épq. ion. et att</i>. ἀνίεις, ἀνίει). <i>Impf. itér. 3 sg</i>. ἀνίεσκε, HÉS. <i>Th. 157. Fut</i>. ἀνήσω, IL. <i>2, 276 ;</i> HH. <i>Cer. 332,</i> mais ἀνέσω, OD. <i>18, 265. Ao.1 ion. et épq</i>. ἀνέηκα, IL. <i>5, 882. Ao.2, 1 et 2 pl</i>. ἀνεῖμεν, ἀνεῖτε ; <i>3 pl. épq</i>. ἄνεσαν, IL. <i>21, 537 ; att</i>. ἀνεῖσαν, THC. <i>5, 32 ; sbj. 3 sg. épq</i>. ἀνήῃ, IL. <i>2, 34 ; opt</i>. ἀνείην, <i>inf</i>. ἀνεῖναι, <i>part</i>. ἀνείς, -εῖσα, -έν. <i>Pf. pass. 3 pl. ion</i>. ἀνέωνται (<i>p</i>. ἀνεῖνται) HDT. <i>2, 165 (vulg</i>. ἀνέονται). — <span>[ᾰνῐ-; <i>att</i>. ᾰνῑ-; ῑ <i>égal. dans les form. hom. 3 sg. impf</i>. ἀνίει, IL. <i>15, 24 ;</i> OD. <i>8, 359, et</i> ἀνιέμενος, IL. <i>22, 80</i>]</span>.<br><span><b>Étym</b>. ἀνά, ἵημι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ανιημι - ἀνίημι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (2)</li>\n<li>Ephésiens (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G448":"<h1>anileos</h1>\n<p>Strong n° 448 <i>Prononciation [an-ee'-leh-oce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sans miséricorde, impitoyable</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀν·ίλεως, ως, ων</b> <span>[ῑ]</span> impitoyable, NT. <i>Jac. 2, 13</i>.<br><span><b>Étym</b>. ἀν-, ἵλεως.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αν-ιλεως - ἀνίλεως</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G449":"<h1>aniptos</h1>\n<p>Strong n° 449 <i>Prononciation [an'-ip-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>non lavé, non nettoyé</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄ·νιπτος, ος, ον :<br>      1</b> non lavé, IL. <i>6, 266 ;</i> HÉS. <i>O. 723 ;</i> LUC. <i>Demon. 4 ;</i><br><b>      2</b> qui ne peut être lavé, ESCHL. <i>Ag. 1459</i>.<br><span><b>Étym</b>. ἀ, νίπτω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-νιπτος - ἄνιπτος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (2)</li>\n</ul>\n</td></tr>\n</table>","G450":"<h1>anistemi</h1>\n<p>Strong n° 450 <i>Prononciation [an-is'-tay-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se lever, élevé\n<ol type=\"a\">\n<li>se relever du sol</li>\n<li>ressusciter de la mort</li>\n<li>naître, apparaître</li>\n</ol>\n</li>\n<li>se lever\n<ol type=\"a\">\n<li>de celui qui est par terre</li>\n<li>de celui qui est assis</li>\n<li>de ceux qui quittent un lieu pour aller ailleurs</li>\n<li>de la mort</li>\n</ol>\n</li>\n<li>s'élever, apparaître, se tenir debout, susciter, s'élever contre quelqu'un</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀν·ίστημι</b> <span>(<i>impf</i>. ἀνίστην, <i>f</i>. ἀναστήσω, <i>ao.1</i> ἀνέστησα, <i>ao.2</i> ἀνέστην, <i>pf</i>. ἀνέστηκα ; <i>pass. f</i>. ἀνασταθήσομαι, <i>ao</i>. ἀνεστάθην, <i>pf</i>. ἀνέστημαι)</span><br><b>A</b> <i>tr. (aux temps suiv. : prés., impf., fut. et ao.1 act. fut. et ao. moy</i>.) :<br><b>   I</b> (ἀνά, en haut) :<br><b>      1</b> faire se lever : τινὰ χειρὸς ἀν. IL. <i>24, 515 ;</i> χειρὸς ἀν. OD. <i>14, 319,</i> faire lever qqn en le tenant par la main ; τινὰ ἐξ ἕδρας, SOPH. <i>Aj. 788 ;</i> ἐκ κλίνης, PLAT. <i>Prot. 317</i> e, faire lever qqn d’un siège, d’une couche ; <i>abs</i>. ἀν. τινά, IL. <i>10, 179 ; 24, 689,</i> faire lever qqn ;<br><b>      2</b> faire lever du lit, IL. <i>10, 32, etc. ;</i> AR. <i>Eccl. 740 ;</i><br><b>      3</b> <i>p. anal</i>. ressusciter, IL. <i>24, 551 ;</i> ESCHL. <i>Ag. 1361 ;</i> SOPH. <i>El. 139 ;</i><br><b>      4</b> <i>fig</i>. relever, sauver (d’une situation misérable, de la servitude) ESCHN. <i>6, 28 ;</i><br><b>      5</b> faire lever (le gibier) XÉN. <i>An. 1, 5, 3 ; Cyr. 2, 4, 20 ; Cyn. 6, 23, etc. ;</i><br><b>      6</b> lever (des armes, des troupes) THC. <i>2, 68, 96, etc. ;</i><br><b>      7</b> <i>fig</i>. exciter : τινά, IL. <i>10, 176,</i> qqn ; τινά τινι, IL. <i>7, 116,</i> exciter qqn contre un adversaire ; πόλεμον, PLUT. <i>Cor. 21,</i> exciter une guerre ;<br><b>      8</b> ériger, élever : πύργον, XÉN. <i>Cyr. 7, 5, 12 ;</i> τρόπαια, PLAT. <i>Tim. 25</i> c, une tour, des trophées ; τινὰ χρυσοῦν <i>ou</i> χαλκοῦν, PLUT. <i>M. 170</i> e, <i>Brut. 1,</i> élever à qqn une statue d’or <i>ou</i> d’airain (<i>les Att. disent</i> χρυσ. <i>ou</i> χαλκ. ἱστάναι, <i>non</i> ἀνιστάναι) ; <i>de même au moy</i>. ἀναστήσασθαι πόλιν, HDT. <i>1, 165,</i> se bâtir une ville ;<br><b>      9</b> lever : πόδα, EUR. <i>H.f. 79,</i> le pied :<br><b>      10</b> faire monter : ἐπὶ τὸ βῆμα, PLUT. <i>M. 784</i> c, faire monter qqn à la tribune :<br><b>      11</b> <i>au moy</i>. faire paraître pour soi : μάρτυρα ἀναστήσασθαι, PLAT. <i>Leg. 937</i> a, produire un témoin en sa faveur ;<br><b>   II</b> (ἀνά, de nouveau) relever, restaurer, rebâtir : τείχη, DÉM. <i>477, 23,</i> des murs ; <i>fig</i>. θεῶν τιμάς, EUR. <i>H.f. 852,</i> restaurer des sacrifices en l’honneur des dieux ;<br><b>   III</b> (ἀνά, en arrière) :<br><b>      1</b> faire se lever et s’éloigner, <i>en parl. de suppliants qu’on éloigne d’un temple,</i> HDT. <i>5, 71 ;</i> THC. <i>1, 137, etc. ;</i> ἀν. στρατόπεδον ἐκ χώρας, POL. <i>29, 11, 10,</i> lever le camp et quitter le pays ; <i>particul</i>. faire émigrer, transporter (un peuple) hors de (son pays) HDT. <i>9, 73 ; avec</i> ἐξ <i>et le gén</i>. THC. <i>2, 27 ; au pass</i>. χώρα ἀνασταθεῖσα, DÉM. <i>367, 20,</i> pays dont les habitants ont été forcés d’émigrer ;<br><b>      2</b> remettre, différer : ἐκκλησίαν ἀναστῆσαι, XÉN. <i>Hell. 2, 4, 42,</i> ajourner une assemblée ;<br><b>B</b> <i>intr. aux temps suiv. (act. ao.2, pf., pl.q.pf. ; moy. prés., impf., fut., ao.2</i>) :<br><b>   I</b> (ἀνά, en haut) :<br><b>      1</b> se lever, <i>en parl. de pers. :</i> ἐξ ἕδρης, IL. <i>19, 77,</i> de son siège ; <i>cf</i>. IL. <i>1, 533 ;</i> ἀπ' ἀκμοθέτοιο ἀνέστη, IL. <i>16, 410</i> (Hèphæstos) se leva et s’éloigna du billot qui portait l’enclume ; ἐπὶ δόρπον, OD. <i>12, 439,</i> se lever (et quitter le tribunal) pour aller prendre le repas du soir ; <i>particul</i>. se lever pour parler, IL. <i>1, 68, etc. ;</i> THC. <i>6, 41 ;</i> XÉN. <i>Hell. 6, 5, 37, etc. ; avec un inf</i>. ἀνέστη μαντεύεσθαι, OD. <i>20, 380,</i> il se leva pour faire une prédiction ; <i>de même,</i> se lever comme champion, IL. <i>23, 709 ; d’où</i> ἀν. τινί, IL. <i>23, 635 ;</i> OD. <i>18, 334,</i> se lever contre qqn, pour lutter contre qqn ; ἀν. ἐξ εὐνῆς, IL. <i>14, 336 ; ou</i> εὐνῆθεν, OD. <i>20, 124, ou abs</i>. ἀν. HÉS. <i>O. 575 ;</i> HDT. <i>1, 31 ;</i> AR. <i>Vesp. 217, etc</i>. se lever, sortir du lit ; <i>p. anal</i>. revenir des enfers, IL. <i>21, 56, etc. ; d’où</i> ressusciter, HDT. <i>3, 62 ;</i> AR. <i>Eccl. 873 ; de même</i> ἀν. ἐκ νόσου, HDT. <i>1, 22 ;</i> ἐκ τῆς νόσου, PLAT. <i>Lach. 195</i> c, <i>etc. ; ou abs</i>. THC. <i>2, 49,</i> relever de maladie ;<br><b>      2</b> s’élever, se dresser, <i>en parl. de tours,</i> EUR. <i>Ph. 824 ;</i> POL. <i>16, 1, 5 ; de statues,</i> PLUT. <i>M. 91</i> a, <i>198</i> f ;<br><b>      3</b> sourdre, jaillir, <i>en parl. d’un fleuve :</i> ἀν. ἐξ ὄρους, PLUT. <i>Pomp. 34,</i> prendre sa source dans une montagne ;<br><b>      4</b> <i>fig</i>. surgir, se produire, <i>en parl. d’événements, de guerres, de troubles,</i> DH. <i>3, 23 ;</i> APP. <i>Civ. 1, 56 ;</i><br><b>   II</b> (ἀνά, en arrière) se lever pour partir, <i>d’où</i> partir : εἰς Ἄργος, EUR. <i>Her. 59,</i> à Argos ; <i>cf</i>. THC. <i>1, 87 ; 7, 49, etc. ;</i> εἰς οἴκημα, PLAT. <i>Phæd. 116</i> a, pour aller dans une maison ; <i>d’où</i> être forcé d’émigrer : ἀναστῆναι ὑπό τινος, THC. <i>1, 12 ; 6, 2 ; 8, 108,</i> être forcé par qqn de quitter son pays ; <i>p. ext. en parl. d’un pays, d’une ville :</i> χώρη ἀνεστηκυῖα, HDT. <i>5, 29,</i> pays dépeuplé par une émigration ; πόλις ἀνέστηκεν δορί, EUR. <i>Hec. 494,</i> la ville est dévastée par la lance.<br><span><b><span class=\"arrow\"></span></b> <i>Act. fut. poét</i>. ἀνστήσω, IL. <i>10, 32 ; 15, 64 ; 24, 551. Ao.1 impér. épq</i>. ἄνστησον, IL. <i>10, 176 ; part. fém</i>. ἀνστήσασα, IL. <i>18, 358. Ao.2, 3 sg. dor</i>. ἀνέστα, SOPH. <i>O.R. 1201 ; 3 pl. épq</i>. ἀνέσταν, IL. <i>1, 533 ; 3 duel épq</i>. ἀνστήτην, IL. <i>1, 305 ; impér. 2 sg</i>. ἄνσταθι <i>ou</i> ἄνστα, THCR. <i>Idyl. 24, 35 ; 2 pl</i>. ἄνστατε, THCR. <i>Idyl. 24, 50 ; sbj. 3 sg. épq</i>. ἀναστήῃ, PD. <i>l. c. ; inf. épq</i>. ἀνστήμεναι, IL. <i>10, 55 ; part. fém. poét</i>. ἀνστᾶσα, IL. <i>14, 336. Pf</i>. ἀνέστακα, <i>au sens trans</i>. SPT. <i>1Reg. 15, 12. Moy. fut. inf. épq</i>. ἀνστήσεσθαι, IL. <i>2, 694</i>.<br><span><b>Étym</b>. ἀνά, ἵστημι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αν-ιστημι - ἀνίστημι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n110 fois dans 109 versets de 10 livres bibliques (NT)\n<ul>\n<li>Matthieu (6)</li>\n<li>Marc (17)</li>\n<li>Luc (27)</li>\n<li>Jean (8)</li>\n<li>Actes (44)</li>\n<li>Romains (2)</li>\n<li>1 Corinthiens (1)</li>\n<li>Ephésiens (1)</li>\n<li>1 Thessaloniciens (2)</li>\n<li>Hébreux (2)</li>\n</ul>\n</td></tr>\n</table>","G451":"<h1>Anna</h1>\n<p>Strong n° 451 <i>Prononciation [an'-nah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Anne (Angl. Anna) = « grâce »\n<ol><li>Une prophétesse de Jérusalem, de la tribu d'Aser, au temps de la présentation du Seigneur au temple</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ἄννα (ἡ)</b> Anna, <i>f</i>. ANTH. <i>8, 27, etc. ;</i> NT. <i><a class=\"ref\" data-r=\"LUK2.36\">Luc 2.36</a> ; au plur</i>. ANTH. <i>8, 28</i>.<br><span><b>Étym</b>. <i>n. hébr</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αννα</font> &lt; חנה - <font face=\"Georgia\">Ἄννα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G452":"<h1>Annas</h1>\n<p>Strong n° 452 <i>Prononciation [an'-nas]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Anne (Angl. Annas) = « humble »\n<ol><li>souverain sacrificateur des Juifs, élevé à la fonction en 6 ou 7 ap. J.C., puis fut déposé par le procurateur de Judée, qui le remplaça par Ismaël, fils de Phabi, puis par Eléazar, fils d'Anne. Anne, même lorsqu'il n'exerça plus ses fonctions, continua à avoir une grande influence.</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<small>VOIR</small> : <b>Ἄννα </b><b>(ἡ)</b> Anna, <i>f</i>. ANTH. <i>8, 27, etc. ;</i> NT. <i><a class=\"ref\" data-r=\"LUK2.36\">Luc 2.36</a> ; au plur</i>. ANTH. <i>8, 28</i>.<br><span><b>Étym</b>. <i>n. hébr</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αννας</font> &lt; חנן - <font face=\"Georgia\">Ἄννας</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Jean (2)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G453":"<h1>anoetos</h1>\n<p>Strong n° 453 <i>Prononciation [an-o'-ay-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>non compris, inintelligible</li>\n<li>ne comprenant pas, non sage, sot, insensé</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀ·νόητος, ος, ον :<br>   I</b> <i>pass. :</i><br><b>      1</b> dont on n’a pas entendu parler, HH. <i>Merc. 80 ;</i><br><b>      2</b> qu’on ne saisit pas par l’esprit (<i>p. opp. à</i> νοητός) PLAT. <i>Phæd. 80</i> b ;<br><b>   II</b> <i>act. :</i><br><b>      1</b> qui ne pense pas, PLAT. <i>Parm. 132</i> c ;<br><b>      2</b> qui ne comprend pas, <i>gén</i>. LUC. ; <i>abs</i>. inintelligent, sot, HDT. <i>1, 87 ;</i> XÉN. <i>Cyr. 2, 2, 15, etc. ;</i> AR. <i>Eq. 1349 ; p. opp. à</i> προνοητικός, XÉN. <i>Mem. 1, 3, 9 ; en parl. d’animaux,</i> ARSTT. <i>H.A. 9, 3, 2, etc. ; de poissons,</i> PLUT. <i>M. 975</i> b ; <i>de choses (pensées, sentiments,</i> SOPH. <i>Aj. 162 ; accusation,</i> XÉN. <i>Œc. 11, 3 ; actions,</i> ISOCR. <i>86</i> a, <i>etc</i>.) : τὰ ἀ. AR. <i>Nub. 417,</i> sottises, folies.<br><span>•<i> Cp</i>. -ότερος, ISOCR. <i>280</i> d. <i>• Sup</i>. -ότατος, XÉN. <i>Œc. 11, 3 ;</i> PLAT. <i>Rsp. 360</i> d, <i>etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Crase avec</i> ὦ ; <i>voc. sg</i>. ὦνόητε, AR. <i>Vesp. 252, Nub. 858 ; plur</i>. ὦνόητοι, AR. <i>Ran. 734 ; mais</i> ὦ ἀνόητοι, AR. <i>Lys. 572</i>.<br><span><b>Étym</b>. ἀ, νοέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-νοητος - ἀνόητος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 5 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Romains (1)</li>\n<li>Galates (2)</li>\n<li>1 Timothée (1)</li>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G454":"<h1>anoia</h1>\n<p>Strong n° 454 <i>Prononciation [an'-oy-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>manque de compréhension, folie déraison</li>\n<li>folie s'exprimant par de la fureur</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄνοια, ας (ἡ) :<br>      1</b> déraison, sottise, folie, SOPH. <i>Ant. 603, etc. ;</i> EUR. <i>Hipp. 397, etc. ;</i> THC. <i>3, 42, etc. ;</i> XÉN. <i>Cyr. 1, 5, 13 ;</i> PLAT. <i>Tim. 86</i> b ; ὑπ' ἀνοίας, ESCHL. <i>Pr. 1079 ;</i> PLAT. <i>Leg. 908</i> e, par un manque de raison ; ἀνοίᾳ πολλῇ χρῆσθαι, ANT. <i>122, 31,</i> être un grand fou ; πολλὴ ἄνοιά (ἐστι) <i>avec l’inf</i>. THC. <i>2, 61,</i> c’est une grande folie de, <i>etc. ;</i> εἰς τοῦτο ἀνοίας ἐληλυθέναι, ISOCR. <i>165</i> c ; εἰς τοῦτ' ἀνοίας ἥκειν, ISOCR. <i>304</i> d, <i>etc</i>. en être venu à ce point de déraison ;<br><b>      2</b> ignorance, SPT. <i>Ps. 21, 2</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Anc. att</i>. ἀνοία, ESCHL. <i>Sept. 402 ;</i> SOPH. <i>fr. 517 ;</i> EUR. <i>Andr. 520. Ion</i>. ἀνοίη, THGN. <i>453 ;</i> HDT. <i>6, 69</i>.<br><span><b>Étym</b>. ἄνοος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-νοια - ἄνοια</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G455":"<h1>anoigo</h1>\n<p>Strong n° 455 <i>Prononciation [an-oy'-go]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>ouvrir</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀν·οίγω</b> <span>(<i>impf</i>. ἀνέῳγον, <i>f</i>. ἀνοίξω, <i>ao</i>. ἀνέῳξα, <i>pf</i>. ἀνέῳχα, <i>pf.2 au sens intr</i>. ἀνέῳγα, <i>d’où pl.q.pf. au sens intr</i>. ἀνεῴγειν ; <i>pass. impf</i>. ἀνεῳγόμην ; <i>f. moy. en att. seul. au sens pass</i>. ἀνοίξομαι ; <i>f. réc</i>. ἀνοιχθήσομαι ; <i>ao</i>. ἀνεῴχθην, <i>d’où inf</i>. ἀνοιχθῆναι ; <i>pf</i>. ἀνέῳγμαι ; <i>pl.q.pf</i> ἀνεῴγμην ; <i>f. ant</i>. ἀνεῴξομαι)</span><br><b>      1</b> ouvrir : πύλας, ESCHL. <i>Ag. 604 ;</i> HDT. <i>3, 117 ;</i> τὰς πύλας, THC. <i>2, 2, etc</i>. les portes ; θύραν, AR. <i>Vesp. 768,</i> une porte ; <i>abs</i>. ἀν. τινί, PLAT. <i>Prot. 310</i> b, ouvrir à qqn ; ἀν. κληῗδα, IL. <i>24, 455,</i> retirer le verrou d’une porte qu’on ouvre ; πῶμα, IL. <i>16, 221,</i> découvrir (qqe ch. en levant) le couvercle ; σήμαντρα, XÉN. <i>Lac. 6, 4,</i> décacheter des sceaux ; οἶνον, THCR. <i>Idyl. 14, 15,</i> mettre du vin en perce ; ἁλὸς κέλευθον ἀν. PD. <i>P. 5, 38,</i> frayer le chemin de la mer ; <i>abs. t. de mar</i>. se mettre au clair, <i>en parl. de marins qui font leurs préparatifs de départ ou de combat (non gagner la haute mer, ni découvrir de loin</i>) XÉN. <i>Hell. 1, 2 ; 5, 3 ; 6, 21 ;</i><br><b>      2</b> <i>fig</i>. découvrir, révéler, déclarer, ESCHL. <i>Suppl. 321</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Formes att. à augment, touj</i>. ἀνε- (<i>v. ci-dessus) ; le pf. pass</i>. ἀνέῳγμαι <i>pour</i> *ἀνήοιγμαι <i>est en outre attesté par deux inscr. att. ; postér. formes en</i> ἠν- : <i>impf</i>. ἤνοιγον, PAUS. <i>4, 26, 8 ;</i> A. TAT. <i>3, 17 (vulg</i>. ἀνέῳγ-) ; APP. <i>Civ. 2, 138 ; ao</i>. ἤνοιξα, APD. <i>2, 5, 4 ;</i> SIB. <i>3, 500, etc. ; ao. pass</i>. ἠνοίχθην, PAUS. <i>2, 35, 4 ;</i> SPT. <i>Ps. 105, 17, etc. ; ao.2</i> ἠνοίγην, LUC. <i>Am. 14 ;</i> Ps.-CALLISTH. <i>1, 14 ; pf</i>. ἤνοιγμαι, JOS. <i>c. Ap. 2, 9 ou</i> ἠνέῳγμαι, DS. <i>23, 16 ;</i> HLD. <i>9, 9. En outre, formes poét., dial. ou rares : Act. Impf. épq</i>. ἀνῷγον, IL. <i>14, 168. Impf. itér</i>. ἀναοίγεσκον, IL. <i>24, 455. Ao. poét</i>. ἀνῷξα, THCR. <i>Idyl. 14, 15 ; ion</i>. ἄνοιξα, HDT. <i>1, 68, etc. Pass. fut.2 réc</i>. ἀνοιγήσομαι, SPT. <i>Neh. 7, 3. Ao. 3 sg. poét</i>. ἀνωΐχθη, NONN. <i>D. 7, 317. Pf. poét</i>. ἀνῷγμαι, THCR. <i>Idyl. 14, 47. — Dans les inscr. att. on rencontre à la fois</i> ἀνοίγω (<i>part. prés. fém</i>. ἀνοίγουσα, CIA. <i>2, 622, 14, 2<sup>e</sup> siècle av. J.C.) et</i> ἀνοίγνυμι (<i>v. ce mot) ; le composé</i> συνανοιγόντων, CIA. <i>1, 32, a, 16 (420/416 av. J.C.) fournit l’exemple le plus ancien ;</i> ἀνοίγω <i>est d’ailleurs la seule forme employée par Thucydide (v. Meisterh. p. 54, 16</i>).<br><span><b>Étym</b>. ἀνά, οἴγω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αν-οιγω - ἀνοίγω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n77 fois dans 75 versets de 9 livres bibliques (NT)\n<ul>\n<li>Matthieu (11)</li>\n<li>Luc (6)</li>\n<li>Jean (11)</li>\n<li>Actes (17)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (2)</li>\n<li>Colossiens (1)</li>\n<li>Apocalypse (27)</li>\n</ul>\n</td></tr>\n</table>","G456":"<h1>anoikodomeo</h1>\n<p>Strong n° 456 <i>Prononciation [an-oy-kod-om-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>reconstruire, rebâtir, relever</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀν·οικοδομέω-ῶ :<br>   I</b> (ἀνά, en haut)  élever des constructions au-dessus de <i>ou</i> en avant de, <i>d’où</i> fortifier, barricader : <i>acc</i>. HDT. <i>1, 186 ;</i> AR. <i>Pax 100 ; particul</i>. barricader (des portes) <i>acc</i>. DS. <i>11, 21 ;</i> PLUT. <i>Cæs. 24 ; fig</i>. être gorgé (<i>litt</i>. blindé) de viandes, <i>en parl. d’athlètes,</i> DS. <i>6, 49 ;</i><br><b>   II</b> (ἀνά, de nouveau) reconstruire, THC. <i>1, 89 ; au pass</i>. XÉN. <i>Hell. 4, 4, 19</i>.<br><span><b>Étym</b>. ἀνά, οἰ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αν-οικοιδομεω - ἀνοικοδομέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G457":"<h1>anoixis</h1>\n<p>Strong n° 457 <i>Prononciation [an'-oix-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>celui qui peut ouvrir (la bouche)</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄνοιξις, εως (ἡ)</b> ouverture, THC. <i>4, 67, 68 ;</i> PLUT. <i>M. 738</i> c, <i>etc</i>.<br><span><b>Étym</b>. ἀνοίγω</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ανοιξις - ἄνοιξις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Ephésiens (1)</li>\n</ul>\n</td></tr>\n</table>","G458":"<h1>anomia</h1>\n<p>Strong n° 458 <i>Prononciation [an-om-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>condition de celui qui est sans loi\n<ol type=\"a\">\n<li>parce qu'il en est ignorant</li>\n<li>parce qu'il la viole</li>\n</ol>\n</li>\n<li>mépris et violation de la loi, iniquité, méchanceté, injustice</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀνομία, ας (ἡ) :<br>      1</b> violation de la loi, illégalité, EUR. <i>I.A. 1095 ; d’où</i> iniquité, injustice, HDT. <i>1, 96, 97 ;</i> EUR. <i>Ion 443 ;</i> ANT. <i>125, 44 ; particul</i>. impiété, EUR. <i>I.T. 275 ;</i><br><b>      2</b> absence de lois, anarchie, désordre, PLAT. <i>Rsp. 575</i> a.<br><span><b>Étym</b>. ἄνομος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ανομια - ἀνομία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n14 fois dans 12 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Romains (3)</li>\n<li>2 Corinthiens (1)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>Tite (1)</li>\n<li>Hébreux (2)</li>\n<li>1 Jean (2)</li>\n</ul>\n</td></tr>\n</table>","G459":"<h1>anomos</h1>\n<p>Strong n° 459 <i>Prononciation [an'-om-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>destitué de la loi (Mosaïque)\n<ol type=\"a\">\n<li>les Gentils, les païens</li>\n</ol>\n</li>\n<li>qui a quitté la loi, violeur de la loi, sans loi, méchant, impie, sans loi, inique</li>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἄ·νομος, ος, ον :<br>      1</b> sans lois, <i>d’où</i> illégitime, impie, criminel, <i>d’ord. en parl. de choses (sacrifice,</i> ESCHL. <i>Ag. 151 ; violence,</i> SOPH. <i>Tr. 1096 ; maux,</i> EUR. <i>Or. 1455 ; monarchie,</i> PLAT. <i>Pol. 302</i> e, <i>etc</i>.) ; ἄνομα, THC. <i>3, 67 ;</i> EUR. <i>Ph. 380,</i> actes illégaux <i>ou</i> arbitraires, illégalités ; <i>joint à</i> κοὐ δίκαια, EUR. <i>I.A. 399 ; en parl. de pers</i>. criminel, XÉN. <i>Mem. 4, 4, 13 ; An. 6, 6, 13 ;</i> PLAT. <i>Leg. 823</i> e, <i>etc. ;</i><br><b>      2</b> sans rythme : ἄνομος νόμος, ESCHL. <i>Ag. 1141,</i> air qui n’en est pas un, <i>càd</i>. chant de malheur.<br><span>•<i> Cp</i>. ἀνομώτερος, ANT. <i>147, 3</i>.<br><span><b>Étym</b>. ἀ, νόμος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-νομος - ἄνομος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 7 versets de 7 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>1 Corinthiens (4)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>1 Timothée (1)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G460":"<h1>anomos</h1>\n<p>Strong n° 460 <i>Prononciation [an-om'-oce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>sans la loi, sans la connaissance de la loi</li>\n<li>pécher par ignorance de la loi Mosaïque</li>\n<li>vivre ignorant de la loi et de la discipline</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀνόμως</b>, <i>adv. :</i><br><b>      1</b> sans lois, sans règle, THC. <i>4, 92 ;</i> EUR. <i>Med. 1000, etc. ;</i><br><b>      2</b> contre la loi, en dehors de la loi, NT. <i>Rom. 2, 12</i>.<br><span>•<i> Cp</i>. -ώτερον, PLAT. <i>Hipp. ma. 285</i> a.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">α-νομως - ἀνόμως</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (2)</li>\n</ul>\n</td></tr>\n</table>","G461":"<h1>anorthoo</h1>\n<p>Strong n° 461 <i>Prononciation [an-orth-o'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se relever, se redresser</li>\n<li>pour une personne déformée</li>\n<li>élever de nouveau, reconstruire</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀν·ορθόω-ῶ :<br>   I</b> (ἀνά, en haut) dresser, lever, EUR. <i>Bacch. 364 ;</i><br><b>   II</b> (ἀνά, de nouveau) rebâtir, relever (un temple, un mur, <i>etc</i>.) HDT. <i>1, 19 ;</i> THC. <i>6, 88 ; fig. :</i><br><b>      1</b> restaurer, rétablir, SOPH. <i>O.R. 46, 51 ;</i> PLAT. <i>Leg. 919</i> d ;<br><b>      2</b> redresser, corriger, remédier à, PLAT. <i>Rsp. 346</i> e.<br><span><b><span class=\"arrow\"></span></b> <i>Augm. et redoubl. régul. : ao</i>. ἀνώρθωσα, EUR. <i>Alc. 1138 ;</i> ISOCR. <i>95</i> a ; <i>pass. impf</i>. ἀνώρθουτο, EUN. <i>fr. 76 L. Dind. ; ao</i>. ἀνωρθώθην, SPT. <i>Ps. 19, 9 ; Ezech. 16, 7 ;</i> NT. <i>Luc. 13, 13 ; pf</i>. ἀνώρθωμαι, SPT. <i>2Reg. 7, 16 ; 1Par. 17, 14 et 24 ; pl.q.pf. act. avec double augm</i>. ἠνωρθώκειν, LIB. <i>Ep. 959 Wolf</i>.<br><span><b>Étym</b>. ἀνά, ὀ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αν-ορθοω - ἀνορθόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G462":"<h1>anosios</h1>\n<p>Strong n° 462 <i>Prononciation [an-os'-ee-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>non saint, impie, méchant, sans religion, sacrilège</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀν·όσιος, ος, ον :<br>      1</b> impie, sacrilège, <i>en parl. de pers</i>. HDT. <i>8, 109 ;</i> ESCHL. <i>Sept. 611 ;</i> SOPH. <i>O.R. 353 ; p. opp. à</i> εὐσεϐής, XÉN. <i>Ap. 19 ; joint à</i> ἄδικος, PLAT. <i>Gorg. 505</i> b, <i>etc. ; en parl. de choses (paroles, actions</i>) ESCHL. <i>Sept. 551, etc. ;</i> SOPH. <i>O.R. 1289, etc. ;</i> EUR. <i>Hipp. 814, etc. ;</i> HDT. <i>8, 105, etc. ; joint à</i> ἀσεϐής, XÉN. <i>Cyr. 8, 7, 22 ;</i> τὰ ἀνόσια, XÉN. <i>Mem. 1, 4, 19,</i> actions <i>ou</i> paroles sacrilèges ;<br><b>      2</b> qui n’a pas reçu la sépulture selon les rites, SOPH. <i>Ant. 1071</i>.<br><span>•<i> Cp</i>. -ώτερος, XÉN. <i>Cyr. 8, 8, 27 ;</i> PLAT. <i>Rsp. 610</i> b. <i>• Sup</i>. -ώτατος, HDT. <i>8, 105 ;</i> XÉN. <i>Hell. 2, 4, 22, etc. ;</i> EUR. <i>Or. 24, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. -α, EUR. <i>Tr. 1315</i>.<br><span><b>Étym</b>. ἀν-, ὅσιος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ανοσιος - ἀνόσιος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Timothée (1)</li>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G463":"<h1>anoche</h1>\n<p>Strong n° 463 <i>Prononciation [an-okh-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>tolérance, patience, action de supporter</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀνοχή, ῆς (ἡ) :<br>   I</b> (ἀνά, en haut) action de tirer (de l’eau) ATH. (ORIB. <i>1, 13 B.-Dar.) ; cf</i>. GEOP. <i>1, 12, 18 ;</i><br><b>   II</b> (ἀνά, en arrière) action de retenir, <i>d’où</i> arrêt, suspension ; <i>particul. :</i><br><b>      1</b> suspension d’armes, armistice, <i>surt. au plur</i>. XÉN. <i>Mem. 4, 4, 17 ;</i> ESCHN. <i>32, 17 ;</i> DL. <i>3, 41 ;</i> ἀνοχὰς ποιεῖσθαι, DÉM. <i>282, 21, ou</i> σπείσασθαι, PLUT. <i>Alex. 55,</i> conclure un armistice ; διδόναι, DH. <i>8, 68,</i> accorder un armistice ;<br><b>      2</b> repos, loisir, HDN <i>3, 6, 21 ;</i> διδόναι τινὶ ἀνοχήν <i>avec l’inf</i>. SPT. <i>1Macc. 12, 25,</i> donner à qqn le loisir <i>ou</i> le temps de, <i>etc. ; au plur</i>. jours fériés des Romains, DC. <i>39, 30, 4 ;</i><br><b>      3</b> patience, longanimité, NT. <i>Rom. 2, 4 ; 3, 26</i>.<br><span><b>Étym</b>. ἀνέχω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ανοχη - ἀνοχή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Romains (2)</li>\n</ul>\n</td></tr>\n</table>","G464":"<h1>antagonizomai</h1>\n<p>Strong n° 464 <i>Prononciation [an-tag-o-nid'-zom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>lutter, combattre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀντ·αγωνίζομαι</b> <span>(<i>impf</i>. ἀντηγωνιζόμην, <i>f</i>. ἀνταγωνιοῦμαι, <i>etc</i>.)</span> <span>[ᾰγ]</span><br><b>      1</b> lutter les armes à la main contre, <i>dat</i>. HDT. <i>5, 109 ;</i> THC. <i>6, 72 ;</i> XÉN. <i>Cyr. 1, 6, 8 ; en gén</i>. lutter <i>ou</i> disputer contre, <i>dat</i>. THC. <i>3, 38 ;</i> περί τινος, AND. <i>29, 12,</i> au sujet de qqe ch. ; οἱ ἀνταγωνιζόμενοί τι, XÉN. <i>Cyr. 8, 2, 27,</i> les parties adverses dans un procès ;<br><b>      2</b> jouer un rôle (tragique) en face d’un autre acteur, PLUT. <i>Dem. 29</i>.<br><span><b>Étym</b>. <i>cf</i>. πρωταγωνιστής.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αντ-αγωνιζομαι - ἀνταγωνίζομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G465":"<h1>antallagma</h1>\n<p>Strong n° 465 <i>Prononciation [an-tal'-ag-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ce qui est donné à la place d'une autre chose, par échange</li>\n<li>ce qui est donné pour acquérir quelque chose</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀντάλλαγμα, ατος (τὸ) :<br>      1</b> échange ; EUR. <i>Or. 1157 ;</i> NT. <i>Matth. 16, 26 ; Marc. 8, 37 ;</i><br><b>      2</b> réconciliation, SPT. <i>Eccl. 44, 16</i>.<br><span><b>Étym</b>. ἀνταλλάσσω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αντ-αλλαγμα - ἀντάλλαγμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G466":"<h1>antanapleroo</h1>\n<p>Strong n° 466 <i>Prononciation [an-tan-ap-lay-ro'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>achever, accomplir\n<ol type=\"a\">\n<li>en <a class=\"ref\" data-r=\"COL1.24\">Colossiens 1.24</a>, le sens est : « je me réjouis de pouvoir ainsi, dans mes souffrances terrestres — qui sont aussi celles du Christ — accomplir ce qui reste à faire pour le douloureux enfantement de l'Eglise, son corps »</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀντ·αναπληρόω-ῶ :<br>      1</b> compléter en échange, <i>d’où</i> substituer, DYSC. <i>Synt. p. 14 ;</i><br><b>      2</b> mettre en balance : πρὸς τὸν εὐπορώτατον τοὺς ἀπορωτάτους, DÉM. <i>182, 22,</i> contrebalancer les plus riches par les plus pauvres.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αντ-αναπληροω - ἀνταναπληρόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G467":"<h1>antapodidomi</h1>\n<p>Strong n° 467 <i>Prononciation [an-tap-od-ee'-do-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>dans un bon sens : rembourser, rendre</li>\n<li>mauvais sens : peine et vengeance</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀντ·αποδίδωμι</b> <span>(<i>f</i>. -αποδώσω, <i>etc</i>.)</span><br><b>   I <i>tr</i>.<br>      1</b> rendre en échange, BATR. <i>187 ;</i> τὸ ὅμοιον, HDT. <i>1, 18 ;</i> τὸ ἴσον, THC. <i>1, 43 ;</i> τὴν ἴσην, ARSTT. <i>Rhet. 2, 2, 16,</i> rendre la pareille ; ἀ. ἀρετήν, THC. <i>4, 19,</i> se montrer généreux en retour ; <i>particul</i>. renvoyer le son, PLUT. <i>Syll. 19, Tim. 27 ;</i> DC. <i>36, 32 ;</i><br><b>      2</b> faire se répondre, faire se correspondre, PLAT. <i>Phæd. 71</i> e ; ARSTT. <i>Rhet. 3, 4 ; en parl. de membres de phrase,</i> D. PHAL. <i>53, 79 ; au pass</i>. être corrélatif de, <i>t. de gramm</i>. DYSC. <i>Pron. 293 ; Synt. 54, 5, etc. ;</i><br><b>   II <i>intr</i>.<br>      1</b> correspondre à, <i>dat</i>. PLAT. <i>Phæd. 72</i> a ; ARSTT. <i>Meteor. 1, 11, 4 ;</i><br><b>      2</b> répondre à, <i>dat</i>. PLAT. <i>Phædr. 236</i> c.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αντ-αποδιδωμι - ἀνταποδίδωμι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 6 versets de 5 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>Romains (2)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G468":"<h1>antapodoma</h1>\n<p>Strong n° 468 <i>Prononciation [an-tap-od'-om-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une chose rétribuée, récompense</li>\n<li>action de rendre, restitution</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀνταπόδομα, ατος (τὸ)</b> ce qui revient en échange, récompense, SPT. <i>Gen. 50, 15 ; Tob. 14, 10 ; Sir. 12, 2 ; 14, 6, etc. ; ou</i> punition, NT. <i>Rom. 11, 9</i>.<br><span><b>Étym</b>. ἀνταποδίδωμι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αντ-αποδομα - ἀνταπόδομα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G469":"<h1>antapodosis</h1>\n<p>Strong n° 469 <i>Prononciation [an-tap-od'-os-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>récompense, récompenser ou rendre à quelqu'un</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀνταπόδοσις, εως (ἡ) :<br>   I</b> restitution en échange, THC. <i>4, 81 ;</i><br><b>   II</b> action de payer en retour, <i>d’où :</i><br><b>      1</b> paiement d’une dette, POL. <i>32, 13, 6 ;</i><br><b>      2</b> <i>p. ext</i>. compensation, POL. <i>6, 5, 3, etc. ;</i><br><b>      3</b> <i>fig</i>. récompense <i>ou</i> châtiment, ARSTT. <i>Nic. 5, 5, 7, etc. ;</i> POL. <i>5, 30, 6 ;</i> DS. <i>20, 100 ;</i> SPT. <i>Esaï. 61, 2, etc. ;</i><br><b>   III</b> <i>t. de gr</i>. corrélation, correspondance de membres de phrase, <i>etc</i>. QUINT. <i>8, 3, 78 ;</i> DYSC. <i>Conj. 503 ;</i><br><b>   IV</b> <i>t. de méd</i>. alternance, action et réaction, HPC. <i>Aph. 1, 12 ;</i><br><b>   V</b> son qui répond à un autre, ARSTT. <i>Aud. 50 ;</i><br><b>   VI</b> changement de direction, POL. <i>4, 43, 5, etc</i>.<br><span><b>Étym</b>. ἀνταποδίδωμι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αντ-αποδοσις - ἀνταπόδοσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G470":"<h1>antapokrinomai</h1>\n<p>Strong n° 470 <i>Prononciation [an-tap-ok-ree'-nom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>contredire, répondre par la contradiction, contester</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀντ·αποκρίνομαι</b> <span>[ῑ]</span><br><b>      1</b> répondre, répliquer, NT. <i>Luc. 14, 6, Rom. 9, 20 ;</i><br><b>      2</b> correspondre à <i>ou</i> avec, <i>t. d’arithm. ; p. ex</i>. 8 <i>et</i> 16 <i>se correspondent comme facteurs de</i> 128 = 8 × 16 ; <i>càd</i>. 16 = ⅛ × 128 ; <i>et</i> 8 = ⅟₁₆ × 128, NICOM. <i>Theol. 77</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αντ-αποκρινομαι - ἀνταποκρίνομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G471":"<h1>antepo</h1>\n<p>Strong n° 471 <i>Prononciation [an-tep'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>parler contre, contredire</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀντεῖπον</b>, <i>v</i>. ἀντιλέγω :<br><br>\n<b>ἀντι·λέγω</b> <span>(<i>f</i>. -λέξω, <i>ao</i>. ἀντέλεξα ; <i>fut. ao. et pf. usuels</i> ἀντερῶ, ἀντεῖπον, ἀντείρηκα, <i>v. ces mots</i>)</span> parler contre, contredire : τινί, THC. <i>5, 30,</i> qqn ; περί τινος, XÉN. <i>Hell. 3, 3, 1,</i> être en désaccord au sujet de qqe ch. ; τινὶ περί τινος, XÉN. <i>Mem. 4, 4, 8, ou</i> ὑπέρ τινος, XÉN. <i>Mem. 3, 5, 12,</i> contredire qqn sur qqe ch. ; <i>avec un acc. de chose :</i> ἀ. τι, SOPH. <i>O.R. 409 ;</i> THC. <i>8, 24, etc</i>. opposer qqe argument ; ἀ. τινί τι, THC. <i>5, 30 ;</i> AR. <i>Lys. 806,</i> alléguer qqe ch. contre qqn ; <i>la prop. suiv. avec</i> ὡς, HDT. <i>8, 77,</i> déclarer, contrairement <i>ou</i> en réponse à d’autres, que ; <i>avec un inf</i>. ἀ. ποιήσειν, THC. <i>1, 28,</i> répliquer qu’on fera ; ἀ. μὴ ποιεῖν, THC. <i>3, 41 ;</i> XÉN. <i>An. 2, 3, 25,</i> conseiller, en réponse à d’autres, de ne pas ; <i>ou avec</i> μὴ οὐ, XÉN. <i>Cyr. 2, 2, 20 ; avec une prop. inf</i>. ἀντ. ἀνάστασιν μὴ εἶναι, NT. <i>Luc. 20, 27,</i> soutenir qu’il n’y a pas de résurrection, nier qu’il y ait résurrection ; <i>abs</i>. parler en opposition, contredire, contester, HDT. <i>9, 42 ; au pass</i>. être contesté, XÉN. <i>Hell. 6, 5, 37 ;</i> τὰ ἀντιλεγόμενα, ESCHN. <i>34, 6,</i> les points controversés, en litige.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αντ-επω - ἀντεῖπον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G472":"<h1>antechomai</h1>\n<p>Strong n° 472 <i>Prononciation [an-tekh'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se tenir à ou contre, retenir, supporter, endurer</li>\n<li>être fermement d'accord, adhérer, s'attacher à quelqu'un</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<u>Mot apparenté</u> : <b>ἀντ·έχω :<br>   I <i>tr</i>.<br>      1</b> tenir devant, <i>avec le rég. ind. au gén. :</i> χεῖρα κρατός, SOPH. <i>O.C. 1650,</i> tenir sa main devant sa figure ; <i>ou au dat. :</i> ὄμμασι δ' ἀντίσχοις τάνδ' αἴγλαν, SOPH. <i>Ph. 830,</i> conserve sur ses traits cette sérénité ;<br><b>      2</b> tenir à l’encontre de : τοὺς χαλινούς, HDN <i>5, 6,</i> retenir les rênes ;<br><b>   II <i>intr</i>.<br>      1</b> tenir contre, résister : τινί, HDT. <i>1, 175 ;</i> THC. <i>2, 65 ;</i> XÉN. <i>Cyr. 6, 4, 18 ; ou</i> πρός τινα, THC. <i>1, 141 ; 2, 76, etc</i>. à qqn ; τινί, THC. <i>1, 11 ; 2, 49, etc. ou</i> πρός τι, HDN <i>1, 12, 3 ; 3, 6, 22,</i> à qqe ch. ; <i>rar. avec l’acc</i>. ἀντ. καμάτους, ANTH. <i>9, 299,</i> supporter des fatigues ; <i>abs</i>. tenir bon, résister, ESCHL. <i>Pers. 413 ;</i> SOPH. <i>Ph. 175 ;</i> XÉN. <i>Cyr. 7, 1, 34 ; en parl. d’une place assiégée,</i> HDT. <i>2, 157 ;</i><br><b>      2</b> <i>p. suite,</i> se maintenir, persister, durer, <i>en parl. d’une maladie,</i> HPC. <i>Fract. 759 ; p. opp. à</i> σήπεσθαι, PLUT. <i>M. 684</i> c ; ἀντ. ἐπὶ πολύ, THC. <i>1, 7 ;</i> βραχὺν χρόνον, DÉM. <i>21, 1,</i> persister longtemps, peu de temps ; <i>avec un part. :</i> ὁ ποταμὸς οὐκ ἀντέσχε τὸ ὕδωρ παρέχων τῷ στρατῷ, HDT. <i>7, 108,</i> le fleuve ne put suffire à fournir de l’eau à l’armée ; <i>p. suite,</i> suffire à, permettre de, <i>abs</i>. ἐς ὅσον ἡ ἐπιστήμη ἀντέχοι, THC. <i>6, 69,</i> tant que la science marchait de pair (avec la bonne volonté, le courage) ;<br><b><i>Moy.</i></b> :<br><b>   I <i>tr.</i></b> tenir devant soi : τραπέζας ἀ. ἰῶν, OD. <i>22, 74,</i> placer des tables devant soi pour se garantir des traits ;<br><b>   II <i>intr</i>.<br>      1</b> s’attacher à : χειρός, HDT. <i>2, 121,</i> à la main (de qqn) ; <i>p. anal</i>. τοῦ πολέμου, HDT. <i>7, 53,</i> persister à faire la guerre ; <i>fig</i>. ἀντέχεσθαι θεοῦ, PD. <i>N. 1, 33,</i> s’attacher à un dieu, l’honorer d’un culte particulier ; ἀ. τῆς ἀρετῆς, HDT. <i>1, 134 ;</i> XÉN. <i>Cyr. 2, 2, 27 ;</i> τῆς ἀληθείας, PLAT. <i>Phil. 58</i> e, s’attacher à la vertu, à la vérité ; τῆς θαλάσσης, THC. <i>1, 13,</i> s’adonner à la mer ;<br><b>      2</b> s’appuyer, SOPH. <i>Ph. 893 ;</i><br><b>      3</b> résister, PLAT. <i>Rsp. 574</i> b, <i>etc. ;</i><br><b>      4</b> disputer, <i>avec 2 gén</i>. AR. <i>Av. 1658,</i> qqe ch. à qqn.<br><span><b>Étym</b>. ἀντί, ἔχω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αντ-εχομαι - ἀντέχομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G473":"<h1>anti</h1>\n<p>Strong n° 473 <i>Prononciation [an-tee']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>opposé à, en avant</li>\n<li>pour, au lieu de cela, à la place de (quelque chose)\n<ol type=\"a\">\n<li>pour ceci, parce que</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀντί</b> <span>[ῐ]</span> <i>prép. avec le gén. :</i><br><b>   I</b> en face de :<br><b>      1</b> <i>au propre :</i> ἰάσπιδες τρεῖς, ἐν αἷς ἔνι ἱππεὺς καὶ ὁπλίτης καὶ Μίνως ἀντὶ τοῦ Μινωταύρου, IG II³, <i>1, 898, 110 (274/273 av. J.C. ; v. Meisterh. p. 173, § 83, 1</i>) trois jaspes, sur lesquels se trouvent un cavalier, un hoplite et Minôs en face du Minotaure (<i>conj</i>. ἀπέναντι) ; ὀπαὶ ἀντὶ τόρμων, HÉRON, mortaises en regard des tenons ;<br><b>      2</b> <i>postér</i>. à l’encontre de, contre, <i>avec l’acc</i>. ἀντὶ τὰς ἐκλύσεις καὶ λειποθυμίας, DIOSC. <i>3, 36,</i> (remède) contre les syncopes et les défaillances ;<br><b>   II</b> au lieu de, à la place de :<br><b>      1</b> <i>en gén</i>. βασιλεύειν ἀντί τινος, XÉN. <i>An. 1, 1, 4,</i> régner à la place de qqn ; πόλεμος ἀντ' εἰρήνης, THC. <i>1, 120,</i> la guerre au lieu de la paix ; πολέμιον ἀ. φίλου καταστῆναι, HDT. <i>1, 87,</i> devenir ennemi au lieu d’ami ; ἀντὶ παίδων ἱκετεύομέν σε, SOPH. <i>O.C. 1326,</i> nous te supplions au nom (<i>litt</i>. à la place) de ces enfants ; <i>qqf. dev. un inf. sans article :</i> ἀντὶ ἄρχεσθαι ὑπ' ἄλλων, ἄρχειν ἁπάντων, HDT. <i>1, 210,</i> au lieu d’être commandé par d’autres, commander à tous ; <i>cf</i>. THC. <i>7, 28 ;</i> XÉN. <i>Cyr. 6, 2, 19 ;</i><br><b>      2</b> à l’égal de : ἀντὶ πολλῶν λαῶν ἐστιν, IL. <i>9, 116,</i> il vaut à lui seul plusieurs armées ; ἀ. κασιγνήτου ξεῖνος, OD. <i>8, 546,</i> hôte qui tient lieu de frère ;<br><b>      3</b> en échange de : ἀμείϐειν τι ἀ. τινος, PD. <i>P. 4, 17,</i> échanger une chose pour une autre ; ἀ. τινος χάριν δοῦναι, IL. <i>23, 650,</i> témoigner de la reconnaissance en échange d’un bienfait ; ἀνθ' ὧν (<i>non</i> ἀντὶ ὧν) ESCHL. <i>Pr. 31, etc</i>. en échange de quoi, pourquoi (<i>qqf</i>. parce que, <i>c</i>. ἀντὶ τούτων ὅτι, SOPH. <i>Ant. 1068</i>) ἀνθ' οὗ, SOPH. <i>Ant. 237 ;</i> pourquoi ? ἀντὶ τοῦ ; pourquoi ? SOPH. <i>O.R. 1021 ; ou</i> en punition de quoi ? pourquoi ? SOPH. <i>O.R. 1155 ; p. suite,</i> en revanche, en compensation de, SOPH. <i>El. 585 ;</i><br><b>      4</b> par succession, par addition : χάριν ἀντὶ χάριτος, NT. <i>Joh. 1, 16,</i> bienfait sur bienfait ; ἑτέραν ἀνθ' ἑτέρας, CHRYS. <i>1, 435 Migne,</i> l’une sur l’autre ;<br><b>      5</b> en comparaison de : αἱρεῖσθαί τι ἀντί τινος, ISOCR. <i>189</i> c ; DÉM. <i>9, 1, etc</i>. choisir une chose de préférence à une autre, préférer une chose à une autre ; τινὰ βούλεσθαι ἀντί τινος, THGN. <i>188,</i> préférer une personne à une autre ; ἓν ἀνθ' ἑνός, PLAT. <i>Rsp. 331</i> b, <i>Leg. 705</i> b, toute comparaison faite (<i>litt</i>. une chose mise à la place d’une autre) ; <i>après un compar. ou un adj. marquant une comparaison :</i> καλὸν θάνατον αἱρετώτερον ἀντὶ αἰσχροῦ βίου, XÉN. <i>Lac. 9, 1,</i> (qu’)une belle mort est bien préférable à une vie honteuse ; ἄλλος ἀντ' ἐμοῦ, ESCHL. <i>Pr. 467 ;</i> SOPH. <i>Aj. 444 ;</i> AR. <i>Nub. 653,</i> un autre que moi.<br><span><b><span class=\"arrow\"></span><br>   I</b> <i>Au lieu de</i> ἀντ' = ἀντ(ί), <i>on lit auj</i>. ἀντ' = ἀντ(ἀ) <i>dans</i> IL. <i>8, 233 ; 15, 415 ;</i> OD. <i>4, 115 ;</i> HÉS. <i>O. 725, et</i> ἀντί' <i>p</i>. ἀντί(α) en face de, IL. <i>21, 481 ;</i><br><b>   II</b> ἀντί <i>se place qqf. après son rég. :</i> IL. <i>23, 650 ;</i> ESCHL. <i>Ag. 1277 conj., mais sans changement d’accent ;</i><br><b>   III</b> <i>En compos</i>. ἀντί <i>signifie :</i><br><b>      1</b> en face, à l’encontre (<i>v</i>. ἀντιϐαίνω, ἀντιϐλέπω) ;<br><b>      2</b> <i>p. suite,</i> en opposition avec (<i>v</i>. ἀντιλέγω) ;<br><b>      3</b> en échange de, en retour (<i>v</i>. ἀντιγράφω, ἀντιδίδωμι), <i>d’où</i> mutuellement (<i>v</i>. ἀντιδεξιόομαι) ;<br><b>      4</b> au lieu de (<i>v</i>. ἀντιϐασιλεύς, ἀνθύπατος) ;<br><b>      5</b> à l’égal de, égal à, semblable à (<i>v</i>. ἀντίδουλος, ἀντίθεος) ;<br><b>      6</b> par correspondance avec (<i>v</i>. ἀντίτυπος).<br><span><b>Étym</b>. <i>indo-europ</i>. *h₂ent-, front ; <i>anc. locat., cf</i>. ἄντα, ἄντην <i>et</i> ἀμφί, <i>lat</i>. ante.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αντι - ἀντί</font>\n<br><br>particule primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Préposition</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n22 fois dans 20 versets de 13 livres bibliques (NT)\n<ul>\n<li>Matthieu (5)</li>\n<li>Marc (1)</li>\n<li>Luc (4)</li>\n<li>Jean (1)</li>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>Ephésiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>Hébreux (2)</li>\n<li>Jacques (1)</li>\n<li>1 Pierre (2)</li>\n</ul>\n</td></tr>\n</table>","G474":"<h1>antiballo</h1>\n<p>Strong n° 474 <i>Prononciation [an-tee-bal'-lo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>discuter, s'adresser l'un à l'autre (par des paroles)</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀντι·ϐάλλω</b> <span>(<i>ao.2</i> ἀντέϐαλον, <i>etc</i>.)</span><br><b>      1</b> lancer des traits à son tour, riposter en lançant des traits, THC. <i>7, 25 ;</i> ἀντ. βέλος, POL. <i>6, 22, 4,</i> renvoyer un trait ; <i>avec un dat</i>. ἀντ. ἀκοντίοις, PLUT. <i>Nic. 25,</i> riposter avec des javelots ; <i>fig</i>. ἀ. λόγους πρὸς ἀλλήλους, NT. <i>Luc. 24, 17,</i> s’entretenir, les uns avec les autres ;<br><b>      2</b> placer l’un contre l’autre, <i>d’où</i> comparer, collationner (deux textes) STR. <i>609, 790 ;</i><br><b><i>Moy.</i></b> ἀ. μορφήν, OPP. <i>C. 3, 16 dout</i>. changer de forme.<br><span><b>Étym</b>. ἀ. βάλλω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αντι-βαλλω - ἀντιβάλλω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G475":"<h1>antidiatithemai</h1>\n<p>Strong n° 475 <i>Prononciation [an-tee-dee-at-eeth'-em-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>se placer en opposition, s'opposer, user de représailles, résister, contredire</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀντι·διατίθημι</b>, prendre des dispositions contre, <i>d’où</i> punir, DS. <i>Exc. 602, 70 ;</i><br><b><i>Moy.</i></b> être dans des dispositions contraires, <i>d’où :</i><br><b>      1</b> résister, LGN <i>17, 1 ;</i><br><b>      2</b> être opposant, NT. <i>2Tim. 2, 25</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αντι-διατιθημαι - ἀντιδιατίθημι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G476":"<h1>antidikos</h1>\n<p>Strong n° 476 <i>Prononciation [an-tid'-ee-kos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>adversaire, opposant\n<ol type=\"a\">\n<li>un adversaire dans un procès</li>\n<li>un adversaire, un ennemi</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀντί·δικος, ου (ὁ)</b> <span>[ῐῐ]</span><br><b>      1</b> adversaire dans un procès, partie adverse, ESCHN. <i>50, 22, etc. ;</i> οἱ ἀ. PLAT. <i>Phædr. 273</i> c, les adversaires, les parties ;<br><b>      2</b> <i>p. suite</i> ennemi, ESCHL. <i>Ag. 41</i>.<br><span><b>Étym</b>. ἀ. δίκη.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αντι-δικος - ἀντίδικος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Luc (2)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G477":"<h1>antithesis</h1>\n<p>Strong n° 477 <i>Prononciation [an-tith'-es-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>opposition, ce qui oppose, objection, action d'opposer</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀντίθεσις, εως (ἡ) :<br>   I</b> opposition, PLAT. <i>Soph. 257</i> e, <i>etc. ;</i> ARSTT. <i>H.A. 2, 11, 3 ; particul. :</i><br><b>      1</b> <i>t. de log</i>. opposition de propositions, ARSTT. <i>Interpr. 10, 3, etc. ;</i><br><b>      2</b> <i>t. de rhét</i>. opposition d’idées <i>ou</i> de mots, antithèse, ISOCR. <i>233</i> b ; ARSTT. <i>Rhet. 3, 9, 9 ;</i><br><b>      3</b> <i>t. de gr</i>. permutation de lettres, EM. <i>156, 11 ; 172, 9 ;</i> HDN GR. <i>π. μ. λ. p. 39, 24 ;</i><br><b>   II</b> résistance, ANTH. <i>12, 200</i>.<br><span><b>Étym</b>. ἀντιτίθημι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αντιθεσις - ἀντίθεσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G478":"<h1>antikathistemi</h1>\n<p>Strong n° 478 <i>Prononciation [an-tee-kath-is'-tay-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>poser à la place d'une autre chose</li>\n<li>se placer dans l'opposition\n<ol type=\"a\">\n<li>disposer des troupes, mettre une armée en ligne de bataille</li>\n<li>résister</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀντι·καθίστημι</b> <span>(<i>ao</i>. -κατέστησα, <i>etc</i>.)</span><br><b>   I <i>tr</i>.<br>      1</b> établir <i>ou</i> poster en face, opposer (une personne, une troupe, <i>etc</i>.) à une autre : τινά τινι, XÉN. <i>Cyr. 1, 6, 43 ;</i> PLAT. <i>Rsp. 591</i> a ; τινὰ πρός τινα, THC. <i>4, 93,</i> placer qqn en face de qqn, opposer une troupe à une autre ;<br><b>      2</b> mettre à la place <i>ou</i> en échange de : τινά, POL. <i>22, 15, 11 ;</i> DH. <i>8, 20, etc. ;</i> DC. <i>39, 13, etc</i>. mettre une personne à la place d’une autre, remplacer une personne par une autre ; τι, HDT. <i>9, 39 ;</i> THC. <i>2, 13,</i> mettre une chose en remplacement d’une autre ; <i>particul</i>. changer les dispositions de qqn, DH. <i>6, 11 ;</i> ἐπί τι, THC. <i>2, 65,</i> dans le sens de qqe ch. ;<br><b>   II</b> <i>intr. (à l’ao.2, au pf.2 act. et au moy.)</i> :<br><b>      1</b> s’établir en face de, s’opposer <i>ou</i> résister à, <i>dat</i>. XÉN. <i>Hipp. 7, 5, etc. ; abs</i>. THC. <i>1, 71 ;</i><br><b>      2</b> prendre <i>ou</i> occuper la place de : τινός <i>ou</i> ἀντί τινος, HDT. <i>2, 37,</i> de qqn.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. pass</i>. -κατεστάθην, XÉN. <i>An. 3, 1, 88. Ion</i>. -κατίστημι, HDT. <i>2, 37, etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αντι-καθιστημι - ἀντικαθίστημι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (2)</li>\n</ul>\n</td></tr>\n</table>","G479":"<h1>antikaleo</h1>\n<p>Strong n° 479 <i>Prononciation [an-tee-kal-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>inviter en retour</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀντι·καλέω-ῶ</b> <span>[κᾰ]</span> inviter à son tour, XÉN. <i>Conv. 1, 15</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αντι-καλεω - ἀντικαλέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G480":"<h1>antikeimai</h1>\n<p>Strong n° 480 <i>Prononciation [an-tik'-i-mahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être opposé à, être contre</li>\n<li>s'opposer</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀντί·κειμαι :<br>      1</b> être situé en face de, <i>gén</i>. HPC. <i>Aër. 282 ; dat</i>. STR. <i>120 ;</i> HDN <i>6, 2, 4 ;</i><br><b>      2</b> <i>p. suite,</i> se correspondre ; <i>fig</i>. τιμὰ ἀγαθοῖσιν ἀντίκειται, PD. <i>I. 6, 26,</i> l’honneur est le prix du mérite ; <i>t. de log. et de rhét. en parl. de propos. qui se correspondent,</i> ARSTT. <i>Metaph. 4, 10, 1, etc. ;</i> ἀντικειμένη λέξις, ARSTT. <i>Rhet. 3, 9, 7,</i> membre de phrase avec antithèse ;<br><b>      3</b> s’opposer à, résister à, <i>dat</i>. SPT. <i>Ex. 23, 22 ; d’où</i> ὁ ἀντικείμενος, l’ennemi, le mauvais esprit, ECCL.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αντι-κειμαι - ἀντίκειμαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 6 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>1 Corinthiens (1)</li>\n<li>Galates (1)</li>\n<li>Philippiens (1)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>1 Timothée (2)</li>\n</ul>\n</td></tr>\n</table>","G481":"<h1>antikru</h1>\n<p>Strong n° 481 <i>Prononciation [an-tee-kroo']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>opposé, face à face</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀντικρύ</b> <span>[ῠ, <i>v. ci-dessous</i>]</span> <i>adv. et prép. :</i><br><b>      1</b> en face de, contre, <i>dat</i>. IL. <i>5, 130 ; gén</i>. IL. <i>8, 301 (en ce sens, les Att. emploient de préférence</i> καταντικρύ, <i>et les écriv. réc</i>. ἄντικρυς <i>et</i> καταντικρύς) ;<br><b>      2</b> en droite ligne, tout droit, IL. <i>13, 137 ;</i> ἀ. δι' ὤμου, IL. <i>4, 481,</i> tout droit à travers l’épaule ; ἀ. κατὰ μέσσον, IL. <i>16, 285,</i> droit au milieu ; ἀ. δι' αὐτῶν, XÉN. <i>Cyr. 7, 1, 30,</i> droit parmi eux ;<br><b>      3</b> tout à fait, IL. <i>7, 362, etc. ;</i> OD. <i>10, 162, etc. ;</i> A. RH. <i>4, 1612</i>.<br><span><b><span class=\"arrow\"></span></b> <span>[ῡ]</span> <i>dans Hom., excepté</i> IL. <i>5, 130, 819</i>. — ἀντικρύ <i>ne se rencontre pas dans les inscr. att. ; mais voy</i>. ἀπαντικρύ <i>et</i> καταντικρύ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αντικρυ - ἀντικρύ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G482":"<h1>antilambanomai</h1>\n<p>Strong n° 482 <i>Prononciation [an-tee-lam-ban'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>s'attacher à une chose</li>\n<li>prendre une personne dans le but de l'aider</li>\n<li>aider, partager, participer aux bienfaits des services rendus par les esclaves</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀντι·λαμϐάνω</b> <span>(<i>f</i>. -λήψομαι, <i>ao.2</i> ἀντέλαϐον, <i>etc</i>.)</span> prendre <i>ou</i> recevoir en échange, <i>acc</i>. EUR. <i>Andr. 741 ;</i> THC. <i>1, 143 ;</i> XÉN. <i>Cyr. 5, 3, 12, etc. ;</i> τί τινος, EUR. <i>H.f. 646,</i> une chose en échange d’une autre ; <i>abs</i>. THGN. <i>108 ;</i><br><b><i>Moy.</i></b> :<br><b>   I</b> se saisir de, s’emparer de : θρόνου, AR. <i>Ran. 777,</i> du trône ; τοῦ ἀσφαλοῦς, THC. <i>3, 22,</i> se mettre en sûreté ; <i>avec un suj. de chose :</i> ὁ λόγος ἀντιλαμϐάνεταί μου, PLAT. <i>Phæd. 88</i> d, le discours me captive ; <i>fig</i>. saisir par l’intelligence, concevoir, comprendre, PLAT. <i>Ax. 370</i> a, <i>blâmé en ce sens, comme vieilli,</i> LUC. <i>Sol. 7 ;</i><br><b>   II</b> s’attacher à (à un vêtement, à un cordage, <i>etc.) gén</i>. PLAT. <i>Prot. 335</i> b, <i>Lach. 184</i> a, <i>etc. ; en parl. de plantes,</i> prendre racine, TH. <i>H.P. 4, 1, 5 ; p. suite, fig. :</i><br><b>      1</b> s’inquiéter de, s’occuper de, faire effort pour : τῆς σωτηρίας, τῆς ἐλευθερίας, THC. <i>2, 61, 62,</i> pour le salut, la liberté ; <i>d’où</i> venir au secours de, prendre parti pour, <i>gén</i>. DS. <i>11, 13 ;</i> NT. <i>Ap. 20, 35 ; abs</i>. soutenir (Hécube qui s’affaisse) EUR. <i>Tr. 464 ;</i><br><b>      2</b> se charger de (d’une guerre, des affaires publiques, <i>etc. ; cf. lat</i>. capessere) <i>gén</i>. THC. <i>2, 8 ;</i> XÉN. <i>Cyr. 2, 3, 6 ;</i> DÉM. <i>15, 5, etc. ;</i><br><b>      3</b> se saisir de, s’attaquer à : τινος, PLAT. <i>Soph. 239</i> d, à qqn ; <i>d’où</i> faire des objections, faire observer, <i>avec</i> ὡς, PLAT. <i>Soph. 251</i> b, objecter que, <i>etc. ;</i><br><b>      4</b> retenir, arrêter : ἵππου, XÉN. <i>Eq. 10, 15, etc</i>. un cheval.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αντι-λαμβανομαι - ἀντιλαμβάνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G483":"<h1>antilego</h1>\n<p>Strong n° 483 <i>Prononciation [an-til'-eg-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>parler contre, contredire, contradiction</li>\n<li>s'opposer à quelqu'un, refuser d'obéir, refuser d'avoir à faire à quelqu'un</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀντι·λέγω</b> <span>(<i>f</i>. -λέξω, <i>ao</i>. ἀντέλεξα ; <i>fut. ao. et pf. usuels</i> ἀντερῶ, ἀντεῖπον, ἀντείρηκα, <i>v. ces mots</i>)</span> parler contre, contredire : τινί, THC. <i>5, 30,</i> qqn ; περί τινος, XÉN. <i>Hell. 3, 3, 1,</i> être en désaccord au sujet de qqe ch. ; τινὶ περί τινος, XÉN. <i>Mem. 4, 4, 8, ou</i> ὑπέρ τινος, XÉN. <i>Mem. 3, 5, 12,</i> contredire qqn sur qqe ch. ; <i>avec un acc. de chose :</i> ἀ. τι, SOPH. <i>O.R. 409 ;</i> THC. <i>8, 24, etc</i>. opposer qqe argument ; ἀ. τινί τι, THC. <i>5, 30 ;</i> AR. <i>Lys. 806,</i> alléguer qqe ch. contre qqn ; <i>la prop. suiv. avec</i> ὡς, HDT. <i>8, 77,</i> déclarer, contrairement <i>ou</i> en réponse à d’autres, que ; <i>avec un inf</i>. ἀ. ποιήσειν, THC. <i>1, 28,</i> répliquer qu’on fera ; ἀ. μὴ ποιεῖν, THC. <i>3, 41 ;</i> XÉN. <i>An. 2, 3, 25,</i> conseiller, en réponse à d’autres, de ne pas ; <i>ou avec</i> μὴ οὐ, XÉN. <i>Cyr. 2, 2, 20 ; avec une prop. inf</i>. ἀντ. ἀνάστασιν μὴ εἶναι, NT. <i>Luc. 20, 27,</i> soutenir qu’il n’y a pas de résurrection, nier qu’il y ait résurrection ; <i>abs</i>. parler en opposition, contredire, contester, HDT. <i>9, 42 ; au pass</i>. être contesté, XÉN. <i>Hell. 6, 5, 37 ;</i> τὰ ἀντιλεγόμενα, ESCHN. <i>34, 6,</i> les points controversés, en litige.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αντι-λεγω - ἀντιλέγω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 9 versets de 5 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>Jean (1)</li>\n<li>Actes (4)</li>\n<li>Romains (1)</li>\n<li>Tite (2)</li>\n</ul>\n</td></tr>\n</table>","G484":"<h1>antilepsis</h1>\n<p>Strong n° 484 <i>Prononciation [an-til'-ape-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>appréhender, percevoir, objection d'un disputeur</li>\n<li>dans le N.T : aider, servir, secourir, entraide</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀντίλημψις, εως (ἡ)</b> NT. <i>1Cor. 12, 28 c</i>. ἀντίληψις II.4.<br><br>\n<b>ἀντίληψις, εως (ἡ) :<br>   I</b> (ἀντιλαμϐάνω) :<br><b>      1</b> action de recevoir en retour <i>ou</i> en échange, <i>d’où</i> importation, THC. <i>1, 120 ;</i><br><b>      2</b> contradiction, <i>d’où</i> incertitude, équivoque, PLUT. <i>Sol. 18 ;</i><br><b>   II</b> (ἀντιλαμϐάνομαι <i>moy</i>.) :<br><b>      1</b> action de se saisir de, de s’attribuer, XÉN. <i>Hell. 3, 5, 5 ;</i><br><b>      2</b> <i>fig</i>. action de percevoir par les sens, DS. <i>3, 14 ;</i> PLUT. <i>M. 625</i> b ; ὑπ' ἀντίλαψιν (<i>dor</i>.) πίπτειν, T. LOCR. <i>100</i> c, tomber sous les sens ;<br><b>      3</b> action de saisir par l’intelligence, conception, intelligence de, PLUT. <i>M. 1140</i> e, <i>1145</i> a ;<br><b>      4</b> action de s’attacher à, TH. <i>C.P. 2, 18, 2 ; d’où</i> action de prendre racine, TH. <i>C.P. 3, 6, 6 ; p. suite,</i> action de protéger, <i>d’où</i> soutien, HPC. <i>Off. 743 ;</i> XÉN. <i>Eq. 5, 7, etc. ; p. ext</i>. défense, secours, NT. <i>1Cor. 12, 28</i> sous la forme ἀντίλημψις ;<br><b>      5</b> action de se charger (d’une chose, d’une entreprise) JOS. ;<br><b>      6</b> action de s’attaquer à, <i>d’où</i> objection, PLAT. <i>Phæd. 87</i> a, <i>etc. ; ou</i> réfutation, HERMOG. <i>3, p. 12 Walz ;</i><br><b>   III</b> (ἀντιλαμϐάνομαι <i>pass</i>.) état de celui qui est saisi (par une maladie), maladie, affection, THC. <i>2, 49</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. ἀντίλαψις, T. LOCR. <i>l. c</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αντι-ληψις - ἀντίλημψις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G485":"<h1>antilogia</h1>\n<p>Strong n° 485 <i>Prononciation [an-tee-log-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>contredire, contradiction</li>\n<li>opposition, rébellion</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀντιλογία, ας (ἡ) :<br>      1</b> parole en réponse, réponse, réplique, THC. <i>4, 59 ;</i><br><b>      2</b> <i>particul</i>. contradiction, contestation, HDT. <i>8, 77 ;</i> THC. <i>1, 31 ;</i> XÉN. <i>Hell. 6, 3, 20 ; joint à</i> λοιδορία, DÉM. <i>1018, 8, etc</i>.<br><span><b>Étym</b>. ἀντίλογος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αντι-λογια - ἀντιλογία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Hébreux (3)</li>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G486":"<h1>antiloidoreo</h1>\n<p>Strong n° 486 <i>Prononciation [an-tee-loy-dor-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>insulter en retour, riposter à des railleries</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀντι·λοιδορέω-ῶ</b>, injurier à son tour, PLUT. <i>M. 88</i> e ; NT. <i>1Petr. 2, 22 ;</i><br><b><i>Moy.</i></b> <i>m. sign</i>. LUC. <i>Conv. 40</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αντι-λοιδορεω - ἀντιλοιδορέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>\tVerbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (2)</li>\n</ul>\n</td></tr>\n</table>","G487":"<h1>antilutron</h1>\n<p>Strong n° 487 <i>Prononciation [an-til'-oo-tron]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>ce qui est donné pour un autre comme prix de son rachat, sa rédemption, en rançon</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀντί·λυτρον, ου (τὸ) :<br>      1</b> rançon, NT. <i>1Tim. 2, 6 ;</i><br><b>      2</b> remède, ORPH. <i>Lith. 587</i>.<br><span><b>Étym</b>. ἀ. λύτρον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αντι-λυτρον - ἀντίλυτρον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G488":"<h1>antimetreo</h1>\n<p>Strong n° 488 <i>Prononciation [an-tee-met-reh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>mesurer en retour, rendre, rembourser</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀντι·μετρέω-ῶ</b> <span>(<i>ao</i>. ἀντεμέτρησα)</span> mesurer en échange, donner en compensation de, <i>dat</i>. LUC. <i>Am. 19 ;</i> NT. <i>Matth. 7, 2 ; Luc. 6, 38</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αντι-μετρεω - ἀντιμετρέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G489":"<h1>antimisthia</h1>\n<p>Strong n° 489 <i>Prononciation [an-tee-mis-thee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>récompense donnée en compensation, récompense, rétribution, rémunération</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀντιμισθία, ας (ἡ)</b> rémunération, salaire, NT. <i>Rom. 1, 27 ; 2Cor. 6, 13</i>.<br><span><b>Étym</b>. ἀντίμισθος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αντι-μιστια - ἀντιμισθία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G490":"<h1>Antiocheia</h1>\n<p>Strong n° 490 <i>Prononciation [an-tee-okh'-i-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Antioche (Angl. Antioch) = « rapide comme un char »\n<ol>\n<li>Capitale de la Syrie, sur le fleuve Oronte, fondée en 300 av. J.C. et ainsi nommée en l'honneur de son fondateur Antiochus. De nombreux Juifs-Grecs y vivaient et c'est là que les disciples de Christ furent appelés pour la première fois Chrétiens.</li>\n<li>Ville de Pisidie, à la frontière de Phrygie, fondée par Seleucus Nicanor. Sous les Romains elle devint « colonie » et fut aussi appelée Césarée</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ἀντιόχεια, ας (ἡ)</b> Antioche (<i>auj</i>. Antakya) <i>v. de Syrie,</i> SPT. <i>1Macc. 3, 37, etc. ;</i> JOS. <i>B.J. 3, 2, 4, etc</i>.<br><span><b>Étym</b>. Ἀντίοχος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αντιοχεια - Ἀντιόχεια</font>\n<br><br>vient de Antiochus (un roi Syrien)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n18 fois dans 17 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (16)</li>\n<li>Galates (1)</li>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G491":"<h1>Antiocheus</h1>\n<p>Strong n° 491 <i>Prononciation [an-tee-okh-yoos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un Antiochien, natif ou habitant d'Antioche</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ἀντιοχεύς, έως (ὁ)</b> habitant <i>ou</i> originaire d’Antioche, POL. <i>5, 59</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αντιοχευς - Ἀντιοχεύς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G492":"<h1>antiparerchomai</h1>\n<p>Strong n° 492 <i>Prononciation [an-tee-par-er'-khom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>passer à l'opposé de, passer de l'autre côté, ne pas tenir compte</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀντι·παρέρχομαι :<br>      1</b> <i>c</i>. ἀντιπαράγω 3, ANTH. <i>12, 8 ;</i> NT. <i>Luc. 10, 31 ;</i><br><b>      2</b> venir au secours, SPT. <i>Sap. 16, 10</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αντι-παρερχομαι - ἀντιπαρέρχομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G493":"<h1>Antipas</h1>\n<p>Strong n° 493 <i>Prononciation [an-tee'-pas]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Antipas = « comme le père », « à la place du père »\n<ol><li>Chrétien de Pergame qui souffrit le martyre</li></ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αντιπας - Ἀντίπας</font>\n<br><br>contraction d'un composé de  et un dérivé de </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G494":"<h1>Antipatris</h1>\n<p>Strong n° 494 <i>Prononciation [an-tip-at-rece']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Antipatris = « proche du père »\n<ol><li>ville située entre Joppé et Césarée, dans une région très fertile, non loin de la côte; reconstruite par Hérode le Grand et nommée Antipatris en l'honneur de son père Antipater</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Αντιπατρις - Ἀντιπατρίς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G495":"<h1>antiperan</h1>\n<p>Strong n° 495 <i>Prononciation [an-tee-per'-an]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>vis à vis, sur des côtes face à face, sur l'autre côté</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀντι·πέραν</b> <span>[ρᾱ]</span> <i>adv</i>., de l’autre côté, en face de : ἡ ἀ. ἤπειρος, XÉN. <i>Hell. 6, 2, 9,</i> le continent opposé : Ἀσιάδ' ἀντιπέρην (<i>ion</i>.) τε, MOSCH. <i>1, 9,</i> l’Asie et le continent opposé.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. -ην, MOSCH. <i>l. c. ;</i> A. RH. <i>2, 177, etc. ;</i> ARAT. <i>273, etc</i>.<br><span><b>Étym</b>. ἀ. πέραν.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αντι-περαν - ἀντιπέραν</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G496":"<h1>antipipto</h1>\n<p>Strong n° 496 <i>Prononciation [an-tee-pip'-to]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>tomber sur, courir contre</li>\n<li>être adversaire, opposé, lutter contre, s'opposer, résister à</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀντι·πίπτω :<br>   I</b> tomber sur <i>ou</i> contre, <i>càd. :</i><br><b>      1</b> rencontrer un obstacle, ARSTT. <i>Probl. 16, 13, etc. ;</i><br><b>      2</b> tomber sur l’ennemi, POL. <i>3, 19, 5 ; 4, 44, 9 ;</i><br><b>      3</b> résister, ARSTT. <i>Probl. 32, 13 ; avec le dat</i>. NT. <i>Ap. 7, 51 ; fig</i>. réfuter, contredire, PLUT. <i>Thes. 28 ;</i><br><b>      4</b> être contraire <i>ou</i> défavorable, POL. <i>16, 2, 1, etc. ;</i><br><b>   II</b> tomber dans une direction opposée, STR. <i>76</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αντι-πιπτω - ἀντιπίπτω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G497":"<h1>antistrateuomai</h1>\n<p>Strong n° 497 <i>Prononciation [an-tee-strat-yoo'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>faire une expédition militaire, prendre le champ, contre quelqu'un</li>\n<li>s'opposer, lutter contre</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<u>Mot apparenté</u> : <b>ἀντι·στρατεύω</b> <span>[ᾰτ]</span> faire une expédition contre, XÉN. <i>Cyr. 8, 8, 26 ;</i><br><b><i>Moy.</i></b> <i>m. sign</i>. DS. <i>Exc. 499, 22</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αντι-στρατευομαι - ἀντιστρατεύομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G498":"<h1>antitassomai</h1>\n<p>Strong n° 498 <i>Prononciation [an-tee-tas'-som-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se ranger en bataille contre</li>\n<li>s'opposer à quelqu'un, résister, s'insurger contre</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀντι·τάσσω</b>, <i>att</i>. <b>-τάττω</b>, <i>litt</i>. ranger en bataille contre, <i>d’où</i> opposer : τινά τινι, HDT. <i>5, 110 ;</i> ESCHL. <i>Sept. 408,</i> une personne à une autre ; <i>au pass</i>. HDT. <i>4, 134 ;</i> τι πρός τι, ESCHN. <i>56, 8,</i> une chose à une autre ;<br><b><i>Moy.</i></b> :<br><b>      1</b> opposer : τί τινι, THC. <i>2, 87 ; 3, 56,</i> une chose à une autre ;<br><b>      2</b> s’opposer à, résister à, <i>dat</i>. THC. <i>3, 83 ;</i> POL. <i>32, 11, 8 ;</i> πρός τινα, HDT. <i>7, 108 ;</i> XÉN. <i>Cyr. 3, 1, 18 ;</i> κατά τινα, XÉN. <i>Hell. 4, 2, 18,</i> résister à qqn.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αντι-τασσομαι - ἀντιτάσσω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 4 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n<li>Jacques (2)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G499":"<h1>antitupos</h1>\n<p>Strong n° 499 <i>Prononciation [an-teet'-oo-pon]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>chose formée d'après un modèle</li>\n<li>une chose qui ressemble à une autre, une imitation, un anti-type, réplique\n<ol type=\"a\">\n<li>quelque chose des temps Messianiques qui est un type, comme le baptême correspond au déluge (<a class=\"ref\" data-r=\"1PE3.21\">1 Pierre 3.21</a>)</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἀντί·τυπος, ος, ον</b> <span>[ῠ]</span><br><b>   I</b> <i>pass. :</i> qui rebondit sur un corps dur : τύπος ἀ. ORACL. (HDT. <i>1, 67</i>) coup de marteau qui rebondit sur l’enclume ; <i>p. anal</i>. répercuté, renvoyé par l’écho, SOPH. <i>Ph. 695 ; 1460 ;</i> A. PL. <i>194 ;</i> réverbéré, réfléchi, <i>en parl. de la lumière,</i> TRIPHIOD. <i>519 ;</i> ANTH. <i>9, 822 ;</i><br><b>   II</b> <i>act. :</i><br><b>      1</b> qui repousse un choc, <i>d’où</i> résistant, <i>càd. en b. part,</i> ferme, solide, <i>en parl. de choses,</i> ARSTT. <i>Probl. 5, 40, 6 ; en mauv. part,</i> opiniâtre, <i>en parl. de pers</i>. PLAT. <i>Theæt. 156</i> a ; <i>p. suite,</i> qui résiste à, adversaire, ennemi de, <i>gén</i>. ESCHL. <i>Sept. 521 ; dat</i>. POL. <i>6, 31, 8 ; en parl. de choses :</i> μάχη ἀ. XÉN. <i>Ages. 6, 2,</i> combat opiniâtre ; <i>en parl. du son,</i> dur, rude, DH. <i>Comp. 22 ;</i> EL. <i>N.A. 12, 15 ;</i><br><b>      2</b> qui reproduit le type de, qui représente : τὸ ἀντίτυπον, représentation exacte, image, NT. <i>Hebr. 9, 24, etc. ; en parl. des saintes espèces qui voilent le corps et le sang de J.C</i>. NAZ. <i>1, 809 Migne ; d’où fig</i>. impression dans l’esprit, PLOT. <i>Enn. 2, 9, 6</i>.<br><span>•<i> Cp</i>. -ώτερος, XÉN. <i>Hipp. 1, 4 ;</i> <i>• Sup</i>. -ώτατος, PLAT. <i>Tim. 62</i> c.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. -η, SOPH. <i>Ant. 134</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">αντιτυπος - ἀντίτυπος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Hébreux (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>"};
